/*!40000 ALTER TABLE `yk_question` DISABLE KEYS */;
INSERT INTO `yk_question` VALUES (1,NULL,1,'Q-OVERVIEW-0001','single_choice','无人机的英文缩写是','C','[{\"optionCode\": \"A\", \"optionContent\": \"UVS\"}, {\"optionCode\": \"B\", \"optionContent\": \"UAS\"}, {\"optionCode\": \"C\", \"optionContent\": \"UAV\"}]','{\"correctAnswer\": \"C\"}','UVS: 无人驾驶车辆系统（ Unmanned Vehicle System ）” 首字母缩写。这一术语通常泛指包括无人机（UAV）、无人地面车辆（UGV）、无人水下车辆（UUV）等在内的各类无人载具系统。\nUAS:无人机系统（UAS： Unmanned Aircraft System）首字母缩写，是指无人机以及与其相关的遥控站（台）、任务载荷和控制链路等组成的系统\nUAV:无人机（UAV： Unmanned Aerial Vehicle），是由控制站管理（包括远程操纵或自主飞行）的航空器。',1,1,'raw-bank/概述.docx#第1题','normal','online',0,'2026-05-13 18:40:36','2026-05-13 22:38:14'),(10,NULL,1,'Q-OVERVIEW-0003','single_choice','近程无人机的活动半径在___________以内','B','[{\"optionCode\": \"A\", \"optionContent\": \"15KM\"}, {\"optionCode\": \"B\", \"optionContent\": \"15~50KM C.50~200KM\"}]','{\"correctAnswer\": \"B\"}','根据无人机分类标准：\n近程无人机的活动半径通常定义为 15~50KM。\n选项A（15KM）属于超近程无人机范围，\n选项C（200~800KM）属于中程无人机范围。',1,3,'raw-bank/概述.docx#第3题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(11,NULL,1,'Q-OVERVIEW-0005','single_choice','任务高度一般在 0-100M 之间的无人机为','A','[{\"optionCode\": \"A\", \"optionContent\": \"超低空无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"低空无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"中空无人机\"}]','{\"correctAnswer\": \"A\"}','根据无人机分类标准：\n超低空无人机：任务高度一般在0-100米\n低空无人机：任务高度一般在100-1000米\n中空无人机：任务高度一般在1000-7000米\n题目中明确任务高度为0-100米，因此对应的是超低空无人机。',1,5,'raw-bank/概述.docx#第5题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(12,NULL,1,'Q-OVERVIEW-0008','single_choice','高空飞行,按照飞行高度区分为','C','[{\"optionCode\": \"A\", \"optionContent\": \"4500 米(含)至 9000 米(含)\"}, {\"optionCode\": \"B\", \"optionContent\": \"8000 米(含)至 12000 米(含)\"}, {\"optionCode\": \"C\", \"optionContent\": \"6000 米(含)至 12000 米(含)\"}]','{\"correctAnswer\": \"C\"}','根据CCAR-71部第十四条规定：\n超低空：100米以下，适用于农林作业、旅游等。\n低空：100米至1000米，适用于训练、侦察等。\n中空：1000米至7000米（部分资料标注为6000米，差异源于不同标准或应用场景），适用于训练、巡逻、轰炸等。\n高空：7000米至15000米（部分资料标注为6000米，差异源于不同标准或应用场景）。\n超高空：15000米以上。\nA：4500米至9000米不符合高空飞行的标准定义；\nB：8000米至12000米范围过窄，未涵盖6000米起始高度；\nC：6000米至12000米完全符合高空飞行的高度划分标准。',1,8,'raw-bank/概述.docx#第8题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(13,NULL,1,'Q-OVERVIEW-0014','single_choice','Ⅱ类无人机是指','C','[{\"optionCode\": \"A\", \"optionContent\": \"起飞全重小于 4KG 的无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"空机重量大于 4KG 的无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"空机质量大于 0.25KG 小于等于 4KG，起飞全重大于 1.5KG 小于等于 7KG 的无人机\"}]','{\"correctAnswer\": \"C\"}','根据无人机分类国家标准：II类无人机的定义为：空机质量大于1.5KG且小于等于4KG，同时起飞全重大于1.5KG且小于等于7KG的无人机。\n选项A描述的是微型无人机（起飞全重≤4KG）的部分特征，但不够准确。\n选项B描述的是III类及以上无人机的特征（空机质量＞4KG）。',1,14,'raw-bank/概述.docx#第14题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(14,NULL,1,'Q-OVERVIEW-0016','single_choice','Ⅳ无人机是指','A','[{\"optionCode\": \"A\", \"optionContent\": \"空机质量大于 15kG 小于等于 116KG，起飞全重大于 25KG 小于等于 150KG 的无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"空机质量大于 25KG 的无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"起飞全重小于 25KG 的无人机\"}]','{\"correctAnswer\": \"A\"}','Ⅳ级别无人机是指空机质量大于15千克但小于等于116千克的无人机（对应选项A的前半部分）题目选项A完整描述为\"空机质量大于15kG小于等于116KG，起飞全重大于25KG小于等于150KG\"，这与标准定义完全一致\n选项B和C的描述与标准定义不符',1,16,'raw-bank/概述.docx#第16题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(15,NULL,1,'Q-OVERVIEW-0018','single_choice','活塞式发动机的 CDI 系统是用（）','A','[{\"optionCode\": \"A\", \"optionContent\": \"电子打火器\"}, {\"optionCode\": \"B\", \"optionContent\": \"排气系统\"}, {\"optionCode\": \"C\", \"optionContent\": \"进气系统\"}]','{\"correctAnswer\": \"A\"}','CDI 系统即电容放电点火系统，其核心部件是电子打火器。\n排气系统主要用于排出燃烧后的废气。\n进气系统负责吸入新鲜空气和燃油混合物。\n所以活塞式发动机的 CDI 系统是用电子打火器。',1,18,'raw-bank/概述.docx#第18题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(16,NULL,1,'Q-OVERVIEW-0020','single_choice','无人机的伺服机构是（）','A','[{\"optionCode\": \"A\", \"optionContent\": \"电动\"}, {\"optionCode\": \"B\", \"optionContent\": \"气动\"}, {\"optionCode\": \"C\", \"optionContent\": \"油动\"}]','{\"correctAnswer\": \"A\"}','无人机的伺服机构主要用于控制无人机的飞行姿态和动作。电动伺服机构因其响应速度快、控制精度高、体积小、重量轻且易于维护，成为无人机的首选。\n气动和油动伺服机构由于体积大、重量重、维护复杂等原因，不常用于无人机。',1,20,'raw-bank/概述.docx#第20题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(17,NULL,1,'Q-OVERVIEW-0022','single_choice','Ⅰ类， Ⅱ类无人机型归（）监管','C','[{\"optionCode\": \"A\", \"optionContent\": \"AOPA\"}, {\"optionCode\": \"B\", \"optionContent\": \"民航局\"}, {\"optionCode\": \"C\", \"optionContent\": \"不需要\"}]','{\"correctAnswer\": \"C\"}','1.无人机分类：I类：空机重量≤0.25kg的微型无人机II类：空机重量>0.25kg且≤4kg的轻型无人机\n2.监管规定：根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，I类、II类无人机由民航局负责监管AOPA（中国航空器拥有者及驾驶员协会）负责培训认证，但不具监管职能\"不需要监管\"不符合现行法规',1,22,'raw-bank/概述.docx#第22题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(18,NULL,1,'Q-OVERVIEW-0024','single_choice','I 级别无人机指','A','[{\"optionCode\": \"A\", \"optionContent\": \"空机质量≤1.5kg，起飞全重≤1.5kg\"}, {\"optionCode\": \"B\", \"optionContent\": \"空机质量≤0.5kg，起飞全重≤1.5kg\"}, {\"optionCode\": \"C\", \"optionContent\": \"空机质量≤1kg，起飞全重≤2.5kgl>\"}]','{\"correctAnswer\": \"A\"}','根据无人机分类的相关标准，\nI级别无人机是指空机质量≤1.5kg且起飞全重≤1.5kg的无人机。选项A明确指出了这一标准.\n而选项B和C的空机质量和起飞全重的限制与I级别无人机的定义不符。',1,24,'raw-bank/概述.docx#第24题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(19,NULL,1,'Q-OVERVIEW-0028','single_choice','将机场从北京搬到拉萨，对哪种飞机影响最大？','A','[{\"optionCode\": \"A\", \"optionContent\": \"油动固定翼\"}, {\"optionCode\": \"B\", \"optionContent\": \"电动固定翼\"}, {\"optionCode\": \"C\", \"optionContent\": \"电动多旋翼\"}]','{\"correctAnswer\": \"A\"}','1、油动固定翼：依赖空气与燃料混合燃烧产生动力，高海拔空气稀薄会导致燃烧效率大幅下降，动力严重不足，影响最大。\n2、电动固定翼：依赖电池供电，不受空气密度直接影响，但螺旋桨效率会降低，影响较小。\n3、电动多旋翼：同样依赖电池，但多旋翼设计对气流变化更敏感，效率会有所下降，但影响小于油动飞机。',1,28,'raw-bank/概述.docx#第28题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(20,NULL,1,'Q-OVERVIEW-0032','single_choice','世界第一架无人机产生的年代为','B','[{\"optionCode\": \"A\", \"optionContent\": \"19 世纪 80 年代\"}, {\"optionCode\": \"B\", \"optionContent\": \"20 世纪 20 年代\"}, {\"optionCode\": \"C\", \"optionContent\": \"20 世纪 40 年代\"}]','{\"correctAnswer\": \"B\"}','世界第一架无人机产生于20世纪20年代。因此，正确答案是B。',1,32,'raw-bank/概述.docx#第32题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(21,NULL,1,'Q-OVERVIEW-0034','single_choice','常规的电子调速器上，中等粗细的几根线是用来连接______的[1分]','B','[{\"optionCode\": \"A\", \"optionContent\": \"自驾仪或遥控接收机\"}, {\"optionCode\": \"B\", \"optionContent\": \"电机\"}, {\"optionCode\": \"C\", \"optionContent\": \"电池\"}]','{\"correctAnswer\": \"B\"}','电子调速器的线缆通常分为几类：\n细线：用于连接自驾仪或遥控接收机，传输控制信号。\n中等粗细的线：用于连接电机，传输较大的电流以驱动电机。\n粗线：用于连接电池，传输更大的电流以供电。因此，中等粗细的线是用来连接电机的。',1,34,'raw-bank/概述.docx#第34题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(22,NULL,1,'Q-OVERVIEW-0036','single_choice','某多轴动力电池标有 6S2P 字样，代表','C','[{\"optionCode\": \"A\", \"optionContent\": \"电池由 6S2P 公司生产\"}, {\"optionCode\": \"B\", \"optionContent\": \"电池组先由 2 个单体串联，再将串联后的6 组并联\"}, {\"optionCode\": \"C\", \"optionContent\": \"电池组先由 6 个单体串联，再将串联后的2 组并联\"}]','{\"correctAnswer\": \"C\"}','1、\"S\"表示串联，\"P\"表示并联\n2、\"6S\"表示有6个电池单体串联\n3、\"2P\"表示将6个串联的电池组再分成2组并联\n4、因此正确连接方式是：先6个单体串联，再将这样的2组并联',1,36,'raw-bank/概述.docx#第36题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(23,NULL,1,'Q-OVERVIEW-0038','single_choice','无人机飞行控制系统速率陀螺是感知飞行器平台______的传感器','B','[{\"optionCode\": \"A\", \"optionContent\": \"姿态角度\"}, {\"optionCode\": \"B\", \"optionContent\": \"角速度\"}, {\"optionCode\": \"C\", \"optionContent\": \"航向角\"}]','{\"correctAnswer\": \"B\"}','速率陀螺是一种传感器，主要用于测量物体的旋转速率，即角速度。在无人机飞行控制系统中，速率陀螺用于感知飞行器平台的角速度变化，从而帮助控制系统进行姿态调整和稳定。因此，速率陀螺感知的是飞行器平台的角速度。',1,38,'raw-bank/概述.docx#第38题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(24,NULL,1,'Q-OVERVIEW-0040','single_choice','如果数传链路下行中断，会发生_____ 的后果','B','[{\"optionCode\": \"A\", \"optionContent\": \"无法在线重规划航线航点及发送任务指令\"}, {\"optionCode\": \"B\", \"optionContent\": \"地面站不再更新无人机的遥测数据\"}, {\"optionCode\": \"C\", \"optionContent\": \"无人机航拍图传图像丢失\"}]','{\"correctAnswer\": \"B\"}','数传链路的下行数据传输主要负责将无人机的遥测数据（如位置、速度、状态等）发送到地面站。如果下行中断，地面站将无法接收到这些数据，导致无法实时监控无人机的状态。因此，地面站不再更新无人机的遥测数据。',1,40,'raw-bank/概述.docx#第40题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(25,NULL,1,'Q-OVERVIEW-0042','single_choice','无人机相对有人机的优势，以下哪条不正确','A','[{\"optionCode\": \"A\", \"optionContent\": \"可性指标高\"}, {\"optionCode\": \"B\", \"optionContent\": \"无需生命支持系统\"}, {\"optionCode\": \"C\", \"optionContent\": \"训练可多依赖于模拟器\"}]','{\"correctAnswer\": \"A\"}','A选项：“可性指标高”表述模糊，通常无人机可靠性可能不如有人机（如复杂环境适应性），此说法可能不正确。\nB选项：无人机无需搭载飞行员，故无需生命支持系统（如氧气、抗压设备），这是明确优势。\nC选项：无人机操作可通过模拟器训练，减少实机训练成本和风险，这也是优势。综合判断，A选项的表述不严谨或不符合实际，是错误选项。',1,42,'raw-bank/概述.docx#第42题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(26,NULL,1,'Q-OVERVIEW-0044','single_choice','在大风中自驾飞行的固定翼民用无人机，航线左转 90','B','[{\"optionCode\": \"A\", \"optionContent\": \"逆风左转 90 度，转出的弯大\"}, {\"optionCode\": \"B\", \"optionContent\": \"顺风左转 90 度，转出的弯大\"}, {\"optionCode\": \"C\", \"optionContent\": \"逆风、顺风左转 90 度，转出的弯一样大\"}]','{\"correctAnswer\": \"B\"}','固定翼无人机在大风中飞行时：\n逆风飞行时，风速会减小无人机的地速，导致转弯半径减小，转出的弯较小。\n顺风飞行时，风速会增加无人机的地速，导致转弯半径增大，转出的弯较大。\n因此，顺风左转90度时，转出的弯比逆风左转90度时更大。',1,44,'raw-bank/概述.docx#第44题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(27,NULL,1,'Q-OVERVIEW-0046','single_choice','_________ 是在无人机具有姿态稳定控制机构的基础上，通过操纵杆控制无人机的俯仰角、滚转角和偏航角，从 而改变无人机的运动','B','[{\"optionCode\": \"A\", \"optionContent\": \"舵面遥控\"}, {\"optionCode\": \"B\", \"optionContent\": \"姿态遥控\"}, {\"optionCode\": \"C\", \"optionContent\": \"指令控制\"}]','{\"correctAnswer\": \"B\"}','A、舵面遥控：直接操纵舵面偏转（如升降舵、副翼等），不涉及姿态角控制，属于更底层的控制方式。\nB、姿态遥控：在无人机具备姿态稳定功能的前提下，通过操纵杆直接控制俯仰角、滚转角和偏航角，从而改变运动状态。\nC、指令控制：通过预设指令（如GPS坐标）控制无人机，无需手动操纵姿态角。\n“通过操纵杆控制姿态角”，符合“姿态遥控”的定义。',1,46,'raw-bank/概述.docx#第46题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(28,NULL,1,'Q-OVERVIEW-0050','single_choice','位置传感器用于感受无人机的位置，是飞行轨迹控制的必要前提_______是典型的位置传感器[1分]','C','[{\"optionCode\": \"A\", \"optionContent\": \"加速度传感器\"}, {\"optionCode\": \"B\", \"optionContent\": \"角速率传感器\"}, {\"optionCode\": \"C\", \"optionContent\": \"GPS 卫星导航接收机\"}, {\"optionCode\": \"C\", \"optionContent\": \"、GPS卫星导航接收机：通过接收卫星信号直接计算无人机的经纬度坐标，是典型的位置传感器。\"}]','{\"correctAnswer\": \"C\"}','1、位置传感器的定义：位置传感器用于检测物体在空间中的位置信息，是飞行控制系统的关键部件。\n2、选项分析：\nA、加速度传感器：用于测量物体的加速度，属于运动传感器，而非直接测量位置。\nB、 角速率传感器（如陀螺仪）：用于测量物体的旋转速率，属于姿态传感器，不直接测量位置。\n3、结论：GPS卫星导航接收机能够直接提供无人机的位置信息，符合题目要求。',1,50,'raw-bank/概述.docx#第50题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(29,NULL,1,'Q-OVERVIEW-0052','single_choice','多旋翼飞行器的螺旋桨','A','[{\"optionCode\": \"A\", \"optionContent\": \"桨根处角速度等于桨尖处角速度\"}, {\"optionCode\": \"B\", \"optionContent\": \"桨根处线速度大于桨尖处线速度\"}, {\"optionCode\": \"C\", \"optionContent\": \"桨根处升力系数小于桨尖处升力系数\"}]','{\"correctAnswer\": \"A\"}','1、角速度分析：螺旋桨旋转时，整个桨叶(从桨根到桨尖)的角速度是相同的，因为它们是刚性连接在同一个旋转轴上。因此选项A\"桨根处角速度等于桨尖处角速度\"是正确的。\n2、线速度分析：线速度v=ωr(ω为角速度，r为半径)桨尖处的半径大于桨根处的半径，因此桨尖处的线速度大于桨根处的线速度。所以选项B\"桨根处线速度大于桨尖处线速度\"是错误的。\n3、升力系数分析：升力系数与气流速度有关，桨尖处线速度大，气流速度大，理论上升力系数会更大。但实际上由于桨尖失速等因素，升力系数分布更复杂，但总体趋势是桨尖处升力系数大于桨根处。因此选项C\"桨根处升力系数小于桨尖处升力系数\"是正确的\n正确答案是A和C。但根据单选题的设定可能需要选择最符合的一个答案，选择A，因为这是螺旋桨运动学的基本特性，而C涉及更复杂的空气动力学分析。',1,52,'raw-bank/概述.docx#第52题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(30,NULL,1,'Q-OVERVIEW-0054','single_choice','利用不育性防治害虫的方法属于','C','[{\"optionCode\": \"A\", \"optionContent\": \"化学防治法\"}, {\"optionCode\": \"B\", \"optionContent\": \"物理机械防治法\"}, {\"optionCode\": \"C\", \"optionContent\": \"生物防治法\"}]','{\"correctAnswer\": \"C\"}','A、化学防治法：使用化学农药杀灭害虫，与不育性无关。\nB、物理机械防治法：通过物理手段如捕杀、隔离等方法防治害虫，不涉及生物技术。\nC、生物防治法：利用生物或其代谢产物防治害虫，不育性防治是通过生物技术使害虫失去繁殖能力，属于此类。',1,54,'raw-bank/概述.docx#第54题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(31,NULL,1,'Q-OVERVIEW-0056','single_choice','全马力飞行时，逆风和顺风两种情况，哪个空速快','C','[{\"optionCode\": \"A\", \"optionContent\": \"顺风\"}, {\"optionCode\": \"B\", \"optionContent\": \"逆风\"}, {\"optionCode\": \"C\", \"optionContent\": \"一样快\"}]','{\"correctAnswer\": \"C\"}','1、空速定义：飞机相对于周围空气的运动速度，由发动机推力和飞机阻力决定。\n2、顺风/逆风影响的是地速（飞机相对于地面的速度），不影响空速：\n顺风时地速=空速+风速\n逆风时地速=空速-风速\n3、题目问的是\"空速\"而非\"地速\"，因此风向变化不会改变空速大小。\n正确答案是C（一样快）。全马力飞行时，无论逆风还是顺风，飞机的空速（发动机产生的速度）保持不变，变化的只是地速。',1,56,'raw-bank/概述.docx#第56题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(32,NULL,1,'Q-OVERVIEW-0058','single_choice','多旋翼飞行器一般常用的电池是哪种','A','[{\"optionCode\": \"A\", \"optionContent\": \"Lipo B.NiMh C.NiCd\"}]','{\"correctAnswer\": \"A\"}','A、Lipo（锂聚合物电池）：高能量密度，重量轻，适合对重量敏感的多旋翼飞行器。放电性能稳定，支持高倍率放电，满足飞行器动力需求。是当前多旋翼飞行器的主流动力电池。\nB、NiMh（镍氢电池）：能量密度较低，重量较大，已逐渐被Lipo取代。\nC、NiCd（镍镉电池）：存在记忆效应，环保性差，已基本淘汰。',1,58,'raw-bank/概述.docx#第58题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(33,NULL,2,'Q-SYSTEM-0002','single_choice','多轴飞行器难以完成那种工作','C','[{\"optionCode\": \"A\", \"optionContent\": \"测绘\"}, {\"optionCode\": \"B\", \"optionContent\": \"直播\"}, {\"optionCode\": \"C\", \"optionContent\": \"超远距离监控\"}]','{\"correctAnswer\": \"C\"}','1、测绘：多轴飞行器配备高清相机和测绘设备，可高效完成地形测绘任务。2、直播：通过实时图传技术，多轴飞行器广泛应用于活动直播等领域。3、超远距离监控：受通信距离（如Wi-Fi/4G覆盖范围）、电池续航时间（通常20～40分钟）和信号稳定性限制，难以持续稳定地完成超远距离监控。',1,2,'raw-bank/系统组成及介绍.docx#第2题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(34,NULL,2,'Q-SYSTEM-0004','single_choice','多轴飞行器都有哪些用途 ①急救灾，②军用侦察，③警用监视，④娱乐，⑤广电行业','C','[{\"optionCode\": \"A\", \"optionContent\": \"①④⑤\"}, {\"optionCode\": \"B\", \"optionContent\": \"②③④\"}, {\"optionCode\": \"C\", \"optionContent\": \"①②③④⑤\"}]','{\"correctAnswer\": \"C\"}','多轴飞行器具有多种用途：① 应急救灾：可用于灾区勘察、物资投送等。② 军用侦察：用于军事侦察任务。③ 警用监视：辅助警方进行监视和侦察。④ 娱乐：如航拍摄影、飞行表演等。⑤ 广电行业：用于影视拍摄等。综上所述，多轴飞行器的用途涵盖了①②③④⑤所有选项。',1,4,'raw-bank/系统组成及介绍.docx#第4题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(35,NULL,2,'Q-SYSTEM-0006','single_choice','无人机燃油箱通气目的之一是','B','[{\"optionCode\": \"A\", \"optionContent\": \"通气增大供油流量\"}, {\"optionCode\": \"B\", \"optionContent\": \"保证向发动机正常供油\"}, {\"optionCode\": \"C\", \"optionContent\": \"通气减小供油流量\"}]','{\"correctAnswer\": \"B\"}','无人机燃油箱通气的主要目的包括：1、平衡油箱内外气压，防止因气压差导致供油不畅2、确保发动机能够持续稳定地获得燃油供应3、避免油箱因负压变形或损坏选项分析：A、通气增大供油流量 - 错误，通气不直接影响流量大小B、保证向发动机正常供油 - 正确，这是通气的主要目的C、通气减小供油流量 - 错误，通气不会减小流量',1,6,'raw-bank/系统组成及介绍.docx#第6题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(36,NULL,2,'Q-SYSTEM-0008','single_choice','无人机地面加油时，必须在场的人员之一是','B','[{\"optionCode\": \"A\", \"optionContent\": \"无人机飞行员\"}, {\"optionCode\": \"B\", \"optionContent\": \"地面消防员\"}, {\"optionCode\": \"C\", \"optionContent\": \"手拿传呼机的指挥员\"}]','{\"correctAnswer\": \"B\"}','根据航空安全规定，无人机地面加油属于危险作业，必须配备专业安全人员。各选项分析：A. 无人机飞行员：主要负责飞行操作，非加油必须人员',1,8,'raw-bank/系统组成及介绍.docx#第8题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(37,NULL,2,'Q-SYSTEM-0010','single_choice','每天飞行结束后,应将燃油油箱加满油,其目的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"尽量减少水汽进入油箱,避免燃油污染\"}, {\"optionCode\": \"B\", \"optionContent\": \"便于第二天尽快飞行\"}, {\"optionCode\": \"C\", \"optionContent\": \"防汽化器式活塞发动机在何时容易出现汽化器回火现象\"}]','{\"correctAnswer\": \"A\"}','A选项正确。加满油箱可减少油箱内空气体积，降低水汽凝结可能性，避免燃油污染。B选项不准确。虽然加满油可能便于飞行，但这不是主要目的。C选项错误。与汽化器回火现象无直接关联。',1,10,'raw-bank/系统组成及介绍.docx#第10题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(38,NULL,2,'Q-SYSTEM-0012','single_choice','在下列参数中,影响涡桨发动机工作寿命的主要是','A','[{\"optionCode\": \"A\", \"optionContent\": \"发动机的排气温度\"}, {\"optionCode\": \"B\", \"optionContent\": \"发动机滑油温度\"}, {\"optionCode\": \"C\", \"optionContent\": \"发动机转速\"}]','{\"correctAnswer\": \"A\"}','A、排气温度：反应燃烧室和涡轮的工作温度，过高会导致材料热疲劳和加速老化，直接影响发动机寿命。',1,12,'raw-bank/系统组成及介绍.docx#第12题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(39,NULL,2,'Q-SYSTEM-0014','single_choice','无人机电气系统一般包括______3 个部分','B','[{\"optionCode\": \"A\", \"optionContent\": \"电源、电缆、接插件\"}, {\"optionCode\": \"B\", \"optionContent\": \"电源、配电系统、用电设备\"}, {\"optionCode\": \"C\", \"optionContent\": \"电源、供电系统、用电设备\"}]','{\"correctAnswer\": \"B\"}','选项A中的\"电缆、接插件\"属于连接部件，不是独立功能系统选项B的\"配电系统\"指电能分配管理部分，与\"电源\"\"用电设备\"构成完整体系选项C的\"供电系统\"表述不准确，实际应指\"配电系统\"正确答案为B选项',1,14,'raw-bank/系统组成及介绍.docx#第14题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(40,NULL,2,'Q-SYSTEM-0016','single_choice','_____两者组合统称为供电系统','C','[{\"optionCode\": \"A\", \"optionContent\": \"电缆和配电\"}, {\"optionCode\": \"B\", \"optionContent\": \"电源和电缆\"}, {\"optionCode\": \"C\", \"optionContent\": \"电源和配电\"}]','{\"correctAnswer\": \"C\"}','1、供电系统定义：指将电能从电源输送到用电设备的完整系统。2、关键组成：电源：产生或引入电能（如发电机、电网）。配电：分配电能至终端设备（含电缆、开关等）。3、排除法：A选项\"电缆和配电\"：电缆属于配电的子部分，不能与配电并列。B选项\"电源和电缆\"：电缆仅为传输媒介，不构成系统核心。C选项正确',1,16,'raw-bank/系统组成及介绍.docx#第16题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(41,NULL,2,'Q-SYSTEM-0018','single_choice','多轴飞行器动力装置多为电动系统的最主要原因是','B','[{\"optionCode\": \"A\", \"optionContent\": \"电动系统尺寸较小且较为廉价\"}, {\"optionCode\": \"B\", \"optionContent\": \"电动系统形式简单且电机速度响应快\"}, {\"optionCode\": \"C\", \"optionContent\": \"电动系统干净且不依赖传统生物燃料\"}]','{\"correctAnswer\": \"B\"}','多轴飞行器选择电动系统的主要原因包括：1、电动系统形式简单，维护方便。2、电机速度响应快，能快速调整飞行状态。3、电动系统干净，无污染，不依赖传统生物燃料。综合来看，电动系统形式简单且电机速度响应快是其最主要的原因。',1,18,'raw-bank/系统组成及介绍.docx#第18题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(42,NULL,2,'Q-SYSTEM-0020','single_choice','从应用上说，涡桨发动机适用于','C','[{\"optionCode\": \"A\", \"optionContent\": \"中低空、低速短距/垂直起降无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"高空长航时无人机/无人战斗机\"}, {\"optionCode\": \"C\", \"optionContent\": \"中高空长航时无人机\"}]','{\"correctAnswer\": \"C\"}','1、涡桨发动机特点：功率大、燃油效率高，适合长时间巡航；螺旋桨推进效率在中低速时更优，但高空性能受限。2、选项分析：',1,20,'raw-bank/系统组成及介绍.docx#第20题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(43,NULL,2,'Q-SYSTEM-0022','single_choice','某多轴电机有 2208 字样，意思是指','C','[{\"optionCode\": \"A\", \"optionContent\": \"该电机最大承受 22V 电压，最小承受 8V 电压\"}, {\"optionCode\": \"B\", \"optionContent\": \"该电机定子高度为 22 毫米\"}, {\"optionCode\": \"C\", \"optionContent\": \"该电机定子直径为 22 毫米\"}]','{\"correctAnswer\": \"C\"}','2208 字样中：前两位数字 \"22\" 表示定子直径为 22 毫米后两位数字 \"08\" 表示定子高度为 8 毫米选项分析：A、错误，2208 不表示电压承受范围；B、错误，2208 中的 22 表示直径而非高度；C、正确，2208 中的 22 表示定子直径为 22 毫米',1,22,'raw-bank/系统组成及介绍.docx#第22题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(44,NULL,2,'Q-SYSTEM-0024','single_choice','关于多轴飞行器使用的动力电机 KV 值描述正确的是','B','[{\"optionCode\": \"A\", \"optionContent\": \"外加 1V 电压对应的每分钟负载转速\"}, {\"optionCode\": \"B\", \"optionContent\": \"外加 1V 电压对应的每分钟空载转速\"}, {\"optionCode\": \"C\", \"optionContent\": \"额定电压值时电机每分钟空载转速\"}]','{\"correctAnswer\": \"B\"}','KV值（Voltage Constant）是电机的一个重要参数，表示外加1V电压时电机每分钟的空载转速。具体来说：A选项：描述的是负载转速，不符合KV值的定义。B选项：描述的是外加1V电压对应的每分钟空载转速，符合KV值的定义。C选项：描述的是额定电压值时的空载转速，不符合KV值的定义。',1,24,'raw-bank/系统组成及介绍.docx#第24题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(45,NULL,2,'Q-SYSTEM-0026','single_choice','某多轴电机标有 1000KV 字样，意义是指','B','[{\"optionCode\": \"A\", \"optionContent\": \"对应每 V 电压，电机提供 1000000 转转速\"}, {\"optionCode\": \"B\", \"optionContent\": \"对应每 V 电压，电机提供 1000 转转速\"}, {\"optionCode\": \"C\", \"optionContent\": \"电机最大耐压 1000KV\"}]','{\"correctAnswer\": \"B\"}','KV值是电机的一个重要参数，表示每伏特电压下电机的空载转速。具体来说：1000KV表示：在1V电压下，电机的空载转速为1000转/分钟。因此，对应每V电压，电机提供1000转转速。选项A的1000000转明显过大，不符合实际；选项C将KV值误解为耐压值，也是错误的。',1,26,'raw-bank/系统组成及介绍.docx#第26题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(46,NULL,2,'Q-SYSTEM-0028','single_choice','多旋翼飞行器动力系统主要使用','C','[{\"optionCode\": \"A\", \"optionContent\": \"步进电机\"}, {\"optionCode\": \"B\", \"optionContent\": \"内转子电机\"}, {\"optionCode\": \"C\", \"optionContent\": \"外转子电机\"}]','{\"correctAnswer\": \"C\"}','多旋翼飞行器需要高扭矩、低转速的动力输出，以实现稳定的飞行。步进电机通常用于精确控制位置，不适合高扭矩需求。内转子电机虽然常见，但在多旋翼飞行器中不如外转子电机高效。外转子电机具有高扭矩、低转速的特点，非常适合多旋翼飞行器的动力需求。',1,28,'raw-bank/系统组成及介绍.docx#第28题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(47,NULL,2,'Q-SYSTEM-0030','single_choice','无刷电机与有刷电机的区别','A','[{\"optionCode\": \"A\", \"optionContent\": \"无刷电机效率较高\"}, {\"optionCode\": \"B\", \"optionContent\": \"有刷电机效率较高\"}, {\"optionCode\": \"C\", \"optionContent\": \"两类电机效率差不多\"}]','{\"correctAnswer\": \"A\"}','1、无刷电机特点：采用电子换向（霍尔传感器控制），无电刷和换向器磨损。减少了机械摩擦和能量损耗，效率可达80%-90%。2、有刷电机特点：依赖机械电刷和换向器换向，存在接触电阻和摩擦损耗。效率通常为60%-80%，且寿命较短。3、结论：无刷电机因结构优势，效率显著高于有刷电机。',1,30,'raw-bank/系统组成及介绍.docx#第30题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(48,NULL,2,'Q-SYSTEM-0032','single_choice','多轴飞行器使用的电调一般为','C','[{\"optionCode\": \"A\", \"optionContent\": \"双向电调\"}, {\"optionCode\": \"B\", \"optionContent\": \"有刷电调\"}, {\"optionCode\": \"C\", \"optionContent\": \"无刷电调\"}]','{\"correctAnswer\": \"C\"}','多轴飞行器一般使用无刷电机，因为无刷电机具有更高的效率、更长的寿命和更轻的重量。无刷电调（电子调速器）是专门为无刷电机设计的，能够精确控制电机的转速和方向。双向电调主要用于需要正反转的应用，而有刷电调则用于有刷电机，这两种电调不适用于多轴飞行器。',1,32,'raw-bank/系统组成及介绍.docx#第32题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(49,NULL,2,'Q-SYSTEM-0034','single_choice','某多轴电调上有 BEC 5V 的字样，意思是指','C','[{\"optionCode\": \"A\", \"optionContent\": \"电调需要从较粗的红线与黑线输入 5V 的电压\"}, {\"optionCode\": \"B\", \"optionContent\": \"电调能从较粗的红线与黑线向外输出 5V 的电压\"}, {\"optionCode\": \"C\", \"optionContent\": \"电调能从较细的红线与黑线向外输出 5V 的电压\"}]','{\"correctAnswer\": \"C\"}','1、BEC 5V表示电调具有5V电池消除器电路功能2、电调的主电源(较粗红线和黑线)用于驱动电机3、BEC输出的5V电压是通过较细的红线与黑线向外提供的4、这个5V电源通常用于给飞控、接收机等设备供电✍️正确答案是C. 电调能从较细的红线与黑线向外输出5V的电压',1,34,'raw-bank/系统组成及介绍.docx#第34题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(50,NULL,2,'Q-SYSTEM-0036','single_choice','遥控器设置电调，需要','C','[{\"optionCode\": \"A\", \"optionContent\": \"断开电机\"}, {\"optionCode\": \"B\", \"optionContent\": \"接上电机\"}, {\"optionCode\": \"C\", \"optionContent\": \"断开动力电源\"}]','{\"correctAnswer\": \"C\"}','设置电调时若电机连接动力电源，可能因信号干扰导致电机突然转动，存在安全隐患。因此必须断开动力电源（C选项），这是最安全的操作方式。断开电机（A选项）不够彻底，接上电机（B选项）则完全错误。',1,36,'raw-bank/系统组成及介绍.docx#第36题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(51,NULL,2,'Q-SYSTEM-0038','single_choice','多轴无人机，电调上较细的白红黑 3 色排线，也叫杜邦线，用来接','C','[{\"optionCode\": \"A\", \"optionContent\": \"电机\"}, {\"optionCode\": \"B\", \"optionContent\": \"机载遥控接收机\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞控\"}]','{\"correctAnswer\": \"C\"}','1、电调的作用：电调（电子调速器）用于控制电机转速，接收飞控信号并驱动电机。2、杜邦线的功能：细白红黑3色排线（杜邦线）主要用于信号传输，而非大电流供电。电机需要大电流供电，通常使用粗线直接连接电调。杜邦线更可能连接飞控（传递控制信号）或接收机（传递遥控信号）。3、排除法：A（电机）：错误，电机连接粗线。B（机载遥控接收机）：部分电调可能通过杜邦线连接接收机，但更常见的是直接连接飞控。C（飞控）：正确，杜邦线通常用于电调与飞控之间的信号通信（如PWM信号）。',1,38,'raw-bank/系统组成及介绍.docx#第38题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(52,NULL,2,'Q-SYSTEM-0040','single_choice','对于多旋翼飞行器动力电源充电，以下哪种充电方法是错误的？','A','[{\"optionCode\": \"A\", \"optionContent\": \"聚合物锂电池单体充电至 4.6V 满电\"}, {\"optionCode\": \"B\", \"optionContent\": \"聚合物锂电池单体充电至 4.2V 满电\"}, {\"optionCode\": \"C\", \"optionContent\": \"磷酸铁锂电池单体充电至 3.6V 满电\"}]','{\"correctAnswer\": \"A\"}','聚合物锂电池的标准满电电压为4.2V，充电至4.6V会过充，可能导致电池损坏或安全风险。磷酸铁锂电池的标准满电电压为3.6V左右，充电至该电压是正确的。因此，选项A的充电方法是错误的。',1,40,'raw-bank/系统组成及介绍.docx#第40题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(53,NULL,2,'Q-SYSTEM-0042','single_choice','某多旋翼飞行器动力电池标有 22.2V，它是','A','[{\"optionCode\": \"A\", \"optionContent\": \"6s 锂电池\"}, {\"optionCode\": \"B\", \"optionContent\": \"22.2s 锂电池\"}, {\"optionCode\": \"C\", \"optionContent\": \"3s 锂电池\"}]','{\"correctAnswer\": \"A\"}','1、锂电池单体电压通常为3.7V。2、总电压=单体电压×s数。3、计算各选项的总电压：A选项：6s × 3.7V = 22.2V（匹配题目电压）B选项：22.2s × 3.7V ≈ 82.14V（远高于22.2V）C选项：3s × 3.7V = 11.1V（低于22.2V）4.只有A选项的总电压与题目一致。',1,42,'raw-bank/系统组成及介绍.docx#第42题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(54,NULL,2,'Q-SYSTEM-0044','single_choice','多轴飞行器一般使用的电池是','A','[{\"optionCode\": \"A\", \"optionContent\": \"聚合物电池\"}, {\"optionCode\": \"B\", \"optionContent\": \"铅酸电池\"}, {\"optionCode\": \"C\", \"optionContent\": \"银锌电池\"}]','{\"correctAnswer\": \"A\"}','聚合物电池具有能量密度高、重量轻、可定制形状等优点，非常适合对重量和续航有严格要求的多轴飞行器。铅酸电池能量密度低、重量大，不适合多轴飞行器。银锌电池成本高、寿命短，也不是多轴飞行器的主流选择。',1,44,'raw-bank/系统组成及介绍.docx#第44题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(55,NULL,2,'Q-SYSTEM-0046','single_choice','同样重量不同类型的电池，容量最大的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"锂聚合物电池\"}, {\"optionCode\": \"B\", \"optionContent\": \"镍镉电池\"}, {\"optionCode\": \"C\", \"optionContent\": \"镍氢电池\"}]','{\"correctAnswer\": \"A\"}','1、锂聚合物电池（锂电池）：能量密度最高，相同重量下可存储最多电量2、镍氢电池：能量密度中等，容量约为锂电池的60%～80%3、镍镉电池：能量密度最低，容量最小且存在记忆效应根据电池技术特性，锂电池在相同重量下具有最大容量。',1,46,'raw-bank/系统组成及介绍.docx#第46题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(56,NULL,2,'Q-SYSTEM-0048','single_choice','以下哪种动力电池放电电流最大','B','[{\"optionCode\": \"A\", \"optionContent\": \"2Ah,30C\"}, {\"optionCode\": \"B\", \"optionContent\": \"30000mAh,5C\"}, {\"optionCode\": \"C\", \"optionContent\": \"20000mAh,5C\"}]','{\"correctAnswer\": \"B\"}','1、统一单位：A选项：2Ah = 2000mAhB选项：30000mAh（无需转换）C选项：20000mAh（无需转换）2、计算放电电流：A选项：2Ah × 30C = 60AB选项：30000mAh × 5C = 30Ah × 5C = 150AC选项：20000mAh × 5C = 20Ah × 5C = 100A',1,48,'raw-bank/系统组成及介绍.docx#第48题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(57,NULL,2,'Q-SYSTEM-0050','single_choice','一般锂聚合电池上都有 2 组线，一组是输出线（粗，红黑各一根），一组是单节锂电池引出线（细，与 S 数有 关），用以监视平衡充电时的电压。下列说法正确的是','B','[{\"optionCode\": \"A\", \"optionContent\": \"6S 电池有 5 根红色引线，1 根黑色引出线\"}, {\"optionCode\": \"B\", \"optionContent\": \"6S 电池有 7 根引出线\"}, {\"optionCode\": \"C\", \"optionContent\": \"6S 电池有 6 根引出线\"}]','{\"correctAnswer\": \"B\"}','1、锂聚合物电池.的“S数”表示串联电池节数（如6S=6节串联）。2、平衡充电时，每节电池需1根引出线监测电压，因此6S电池需要6根引出线（对应6节电池）+1根总负极线=7根引出线。3、选项A错误：红色/黑色引线描述混淆，且数量不对（应为7根）4、选项C错误：遗漏总负极线，实际应为7根。',1,50,'raw-bank/系统组成及介绍.docx#第50题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(58,NULL,2,'Q-SYSTEM-0052','single_choice','无人机在增稳飞行控制模式下，飞控子系统__________控制','A','[{\"optionCode\": \"A\", \"optionContent\": \"参与\"}, {\"optionCode\": \"B\", \"optionContent\": \"不参与\"}, {\"optionCode\": \"C\", \"optionContent\": \"不确定\"}]','{\"correctAnswer\": \"A\"}','在增稳飞行控制模式下，飞控子系统的主要作用是辅助飞行员保持飞行器的稳定性。因此，飞控子系统会参与控制，但不会完全接管飞行控制权。这种模式下，飞控子系统会通过调整飞行器的姿态和动力来减少飞行员的操作负担，确保飞行稳定。',1,52,'raw-bank/系统组成及介绍.docx#第52题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(59,NULL,2,'Q-SYSTEM-0054','single_choice','目前多旋翼飞行器飞控市场上的 APM 飞控的特点是','C','[{\"optionCode\": \"A\", \"optionContent\": \"可以应用于各种特种飞行器\"}, {\"optionCode\": \"B\", \"optionContent\": \"基于 ANDROID 开发\"}, {\"optionCode\": \"C\", \"optionContent\": \"配有地面站软件，代码开源\"}]','{\"correctAnswer\": \"C\"}','APM飞控是开源飞控系统。A选项，APM飞控虽应用广泛，但不能说可应用于各种特种飞行器，表述过于绝对。B选项，APM飞控不是基于ANDROID开发。C选项，APM飞控配有地面站软件，且代码开源，这是其显著特点。',1,54,'raw-bank/系统组成及介绍.docx#第54题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(60,NULL,2,'Q-SYSTEM-0056','single_choice','属于无人机飞控子系统功能的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"无人机姿态稳定与控制\"}, {\"optionCode\": \"B\", \"optionContent\": \"无人机任务设备管理与控制\"}, {\"optionCode\": \"C\", \"optionContent\": \"信息收集与传递\"}]','{\"correctAnswer\": \"A\"}','1、选项A：无人机姿态稳定与控制是飞控子系统的核心功能，直接影响飞行稳定性。2、选项B：任务设备管理与控制属于任务载荷系统的职责，而非飞控子系统。3、选项C：信息收集与传递通常由通信或感知系统完成，不属于飞控范畴。',1,56,'raw-bank/系统组成及介绍.docx#第56题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(61,NULL,2,'Q-SYSTEM-0058','single_choice','____是无人机完成起飞、空中飞行、执行任务、返场回收等整个飞行过程的核心系统，对无人机实现全权控制与管 理，因此该子系统之于无人机相当于驾驶员之于有人机，是无人机执行任务的关键。','B','[{\"optionCode\": \"A\", \"optionContent\": \"飞控计算机\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞控子系统\"}, {\"optionCode\": \"C\", \"optionContent\": \"导航子系统\"}]','{\"correctAnswer\": \"B\"}','根据题目描述，该系统需要负责无人机从起飞到返场回收的全过程控制与管理。飞控子系统（B）正是无人机的核心控制系统，负责飞行姿态、轨迹控制等关键功能。飞控计算机（A）是飞控子系统的组成部分，导航子系统（C）主要负责定位与路径规划，不涵盖全权控制功能。',1,58,'raw-bank/系统组成及介绍.docx#第58题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(62,NULL,2,'Q-SYSTEM-0060','single_choice','飞控子系统可以不具备如下功能：______','C','[{\"optionCode\": \"A\", \"optionContent\": \"姿态稳定与控制\"}, {\"optionCode\": \"B\", \"optionContent\": \"导航与制导控制\"}, {\"optionCode\": \"C\", \"optionContent\": \"任务分配与航迹规划\"}]','{\"correctAnswer\": \"C\"}','飞控子系统的主要功能包括：1、姿态稳定与控制：保持飞行器的稳定姿态。2、导航与制导控制：控制飞行器的飞行路径和方向。任务分配与航迹规划通常由任务管理系统或地面控制站负责，不属于飞控子系统的基本功能。✍️总结选择C. 任务分配与航迹规划。',1,60,'raw-bank/系统组成及介绍.docx#第60题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(63,NULL,2,'Q-SYSTEM-0062','single_choice','以下属于导航飞控系统组成部分的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"传感器\"}, {\"optionCode\": \"B\", \"optionContent\": \"发动机\"}, {\"optionCode\": \"C\", \"optionContent\": \"重心\"}]','{\"correctAnswer\": \"A\"}','1、传感器（A）：是导航飞控系统的关键组成部分，用于实时测量飞行器的姿态、速度、位置等参数（如陀螺仪、加速度计、磁力计等），为控制系统提供数据输入。2、发动机（B）：属于动力系统，负责提供飞行所需的推力，但不属于飞控系统的直接组成部分。飞控系统通过控制信号调节发动机输出，但发动机本身并非飞控硬件。3、重心（C）：是飞行器的物理属性，影响飞行稳定性，但属于被动参数而非主动控制组件。飞控系统通过传感器感知重心变化的影响，但重心本身不是系统部件。',1,62,'raw-bank/系统组成及介绍.docx#第62题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(64,NULL,2,'Q-SYSTEM-0064','single_choice','不应属于无人机飞控计算机任务范畴的是?','A','[{\"optionCode\": \"A\", \"optionContent\": \"数据中继\"}, {\"optionCode\": \"B\", \"optionContent\": \"姿态稳定与控制\"}, {\"optionCode\": \"C\", \"optionContent\": \"自主飞行控制\"}]','{\"correctAnswer\": \"A\"}','1、姿态稳定与控制（B）：飞控计算机的核心功能之一，通过传感器数据实时调整无人机姿态。2、自主飞行控制（C）：飞控计算机根据预设航线或算法实现自主飞行决策。3、数据中继（A）：属于通信系统任务，用于传输数据至地面站或其他设备，非飞控计算机直接职责。',1,64,'raw-bank/系统组成及介绍.docx#第64题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(65,NULL,2,'Q-SYSTEM-0066','single_choice','多旋翼飞行器上的链路天线应尽量______飞控和 GPS 天线安装','C','[{\"optionCode\": \"A\", \"optionContent\": \"贴合\"}, {\"optionCode\": \"B\", \"optionContent\": \"靠近\"}, {\"optionCode\": \"C\", \"optionContent\": \"远离\"}]','{\"correctAnswer\": \"C\"}','多旋翼飞行器的链路天线用于通信，飞控和GPS天线分别用于飞行控制和定位。如果链路天线与飞控和GPS天线过于靠近，可能会产生电磁干扰，影响飞行器的正常工作。因此，为了减少干扰，链路天线应尽量远离飞控和GPS天线。',1,66,'raw-bank/系统组成及介绍.docx#第66题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(66,NULL,2,'Q-SYSTEM-0068','single_choice','活塞发动机在慢车状态下工作时间过长，易带来的主要危害是','A','[{\"optionCode\": \"A\", \"optionContent\": \"电嘴挂油积炭\"}, {\"optionCode\": \"B\", \"optionContent\": \"滑油消耗量过大\"}, {\"optionCode\": \"C\", \"optionContent\": \"汽缸头温度过高\"}]','{\"correctAnswer\": \"A\"}','活塞发动机在慢车状态下，发动机的转速较低，燃油燃烧不完全，容易导致电嘴挂油积炭。滑油消耗量主要与发动机的工作负荷和温度有关，慢车状态下滑油消耗量不会显著增加。汽缸头温度在慢车状态下通常较低，不会过高。',1,68,'raw-bank/系统组成及介绍.docx#第68题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(67,NULL,2,'Q-SYSTEM-0070','single_choice','目前主流的民用无人机所采用的动力系统通常为活塞式发动机和------两种。','C','[{\"optionCode\": \"A\", \"optionContent\": \"涡喷发动机\"}, {\"optionCode\": \"B\", \"optionContent\": \"涡扇发动机\"}, {\"optionCode\": \"C\", \"optionContent\": \"电动机\"}]','{\"correctAnswer\": \"C\"}','民用无人机动力系统主要分为两类：1、活塞式发动机：适用于较大载重或长时间飞行的无人机2、电动机：具有重量轻、噪声小、维护简单等优点，是目前消费级和部分工业级无人机的主流选择3、涡喷发动机和涡扇发动机主要用于高速飞行器，不适用于大多数民用无人机。',1,70,'raw-bank/系统组成及介绍.docx#第70题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(68,NULL,2,'Q-SYSTEM-0072','single_choice','无人机通过控制舵面_____和发动机节风门来实现无人机控制','A','[{\"optionCode\": \"A\", \"optionContent\": \"伺服执行机构\"}, {\"optionCode\": \"B\", \"optionContent\": \"操纵杆\"}, {\"optionCode\": \"C\", \"optionContent\": \"脚蹬\"}]','{\"correctAnswer\": \"A\"}','1、无人机控制系统组成：伺服执行机构：负责接收控制信号并驱动舵面和发动机节风门飞控计算机：计算控制指令传感器：提供飞行状态数据各选项分析：A、伺服执行机构：直接执行控制指令，是正确B、操纵杆：是人工控制设备，不适用于自动控制C、脚蹬：主要用于无人机的方向控制',1,72,'raw-bank/系统组成及介绍.docx#第72题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(69,NULL,2,'Q-SYSTEM-0074','single_choice','无人机配平的主要考虑是_____沿纵轴的前后位置','C','[{\"optionCode\": \"A\", \"optionContent\": \"气动焦点\"}, {\"optionCode\": \"B\", \"optionContent\": \"发动机\"}, {\"optionCode\": \"C\", \"optionContent\": \"重心\"}]','{\"correctAnswer\": \"C\"}','1、气动焦点：是空气动力作用的虚拟点，影响飞行姿态但非配平直接调整对象。2、发动机：提供推力，其位置可能影响重心，但配平时直接调整的是重心而非发动机本身。3、重心：是无人机各部件重量的合力作用点，沿纵轴的前后位置直接影响俯仰平衡，需通过配平调整（如调整电池或载荷位置）。',1,74,'raw-bank/系统组成及介绍.docx#第74题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(70,NULL,2,'Q-SYSTEM-0076','single_choice','计算无人机装载重量和重心的方法不包括：______','B','[{\"optionCode\": \"A\", \"optionContent\": \"计算法\"}, {\"optionCode\": \"B\", \"optionContent\": \"坐标法\"}, {\"optionCode\": \"C\", \"optionContent\": \"查表法\"}]','{\"correctAnswer\": \"B\"}','计算法：通过数学公式直接计算重量和重心位置，是基础且常用的方法。坐标法：通常用于确定位置坐标，而非直接计算重量和重心，属于非常规方法。查表法：通过预先编制的表格查询数据，是辅助计算的方法。根据无人机领域专业知识，坐标法不属于计算重量和重心的常规方法。',1,76,'raw-bank/系统组成及介绍.docx#第76题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(71,NULL,2,'Q-SYSTEM-0078','single_choice','无人机地面站显示系统应能显示_____信息','B','[{\"optionCode\": \"A\", \"optionContent\": \"无人机飞行员状态\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞机状态及链路．载荷状态\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行空域信息\"}]','{\"correctAnswer\": \"B\"}','无人机地面站显示系统的主要功能是：1、显示飞机状态（如高度、速度、位置等）2、显示通信链路状态（如信号强度、连接状态等）3、显示载荷状态（如相机、传感器等工作状态）选项分析：A、无人机飞行员状态 - 地面站主要关注飞机本身状态，而非飞行员生理状态B、飞机状态及链路，载荷状态 - 这是地面站的核心显示内容C、飞行空域信息 - 虽然重要，但不是地面站必须实时显示的主要信息',1,78,'raw-bank/系统组成及介绍.docx#第78题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(72,NULL,2,'Q-SYSTEM-0080','single_choice','无人机系统通讯链路主要包括：指挥与控制（C．&C．），感知和规避（S&A．）_____三种','A','[{\"optionCode\": \"A\", \"optionContent\": \"空中交通管制（ATC）\"}, {\"optionCode\": \"B\", \"optionContent\": \"视频通信\"}, {\"optionCode\": \"C\", \"optionContent\": \"通信中继\"}]','{\"correctAnswer\": \"A\"}','无人机系统通讯链路主要包括三种：指挥与控制（C.&C.），感知和规避（S&A.），以及空中交通管制（ATC）。视频通信和通信中继虽然也是通讯方式，但不属于无人机系统通讯链路的主要组成部分。',1,80,'raw-bank/系统组成及介绍.docx#第80题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(73,NULL,2,'Q-SYSTEM-0082','single_choice','_____航空器平台结构通常包括机翼、机身、尾翼和起落架等','C','[{\"optionCode\": \"A\", \"optionContent\": \"单旋翼\"}, {\"optionCode\": \"B\", \"optionContent\": \"多旋翼\"}, {\"optionCode\": \"C\", \"optionContent\": \"固定翼\"}]','{\"correctAnswer\": \"C\"}','固定翼航空器的平台结构通常包括机翼、机身、尾翼和起落架等基本部件。机翼用于产生升力，机身用于装载人员和货物，尾翼用于稳定和控制飞行方向，起落架用于起飞和降落。单旋翼和多旋翼航空器则主要依靠旋翼产生升力，其结构与固定翼航空器有显著区别。',1,82,'raw-bank/系统组成及介绍.docx#第82题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(74,NULL,2,'Q-SYSTEM-0084','single_choice','______功能通常包括指挥调度、任务规划、操作控制、显示记录等功能','B','[{\"optionCode\": \"A\", \"optionContent\": \"数据链路分系统\"}, {\"optionCode\": \"B\", \"optionContent\": \"无人机地面站系统\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞控与导航系统\"}]','{\"correctAnswer\": \"B\"}','1、数据链路分系统（A）：主要负责无人机与地面站之间的通信传输，不涉及任务规划等高级功能。2、无人机地面站系统（B）：是地面控制中心，专门负责：指挥调度整个飞行任务制定飞行任务规划实时操作控制无人机显示飞行数据和记录飞行日志3、飞控与导航系统（C）：主要负责飞行姿态控制和导航定位，不涉及任务规划等地面控制功能。',1,84,'raw-bank/系统组成及介绍.docx#第84题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(75,NULL,2,'Q-SYSTEM-0086','single_choice','______主要是由飞行操纵、任务载荷控制、数据链路控制和通信指挥等组成，可完成对无人机机载任务载荷等的操 纵控制。','B','[{\"optionCode\": \"A\", \"optionContent\": \"指挥处理中心\"}, {\"optionCode\": \"B\", \"optionContent\": \"无人机控制站\"}, {\"optionCode\": \"C\", \"optionContent\": \"载荷控制站\"}]','{\"correctAnswer\": \"B\"}','1、指挥处理中心：主要负责任务规划、数据处理等高层决策功能，不直接控制飞行和载荷。2、无人机控制站：集成飞行操纵、任务载荷控制、数据链路控制等功能，是直接操控无人机的核心系统。3、载荷控制站：专门负责任务载荷的操作，不涉及飞行控制等综合功能。题干描述的功能组合完全符合无人机控制站的定义。',1,86,'raw-bank/系统组成及介绍.docx#第86题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(76,NULL,2,'Q-SYSTEM-0088','single_choice','地面控制站飞行参数综合显示的内容包括：______','A','[{\"optionCode\": \"A\", \"optionContent\": \"飞行与导航信息、数据链状态信息、设备状态信息、指令信息\"}, {\"optionCode\": \"B\", \"optionContent\": \"导航信息显示、航迹绘制显示以及地理信息的显示\"}, {\"optionCode\": \"C\", \"optionContent\": \"告警信息、地图航迹显示信息\"}]','{\"correctAnswer\": \"A\"}','地面控制站飞行参数综合显示包含多方面重要信息。飞行与导航信息能反映飞行状态和位置等；数据链状态信息可了解数据传输状况；设备状态信息有助于掌握设备工作情况；指令信息则明确操作指令相关内容。而选项 B 主要侧重于显示方面，选项 C 不够全面。✍️结答案选 A，即飞行与导航信息、数据链状态信息、设备状态信息、指令信息。',1,88,'raw-bank/系统组成及介绍.docx#第88题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(77,NULL,2,'Q-SYSTEM-0090','single_choice','飞行控制是指采用______对无人机在空中整个飞行过程的控制','C','[{\"optionCode\": \"A\", \"optionContent\": \"遥感方式\"}, {\"optionCode\": \"B\", \"optionContent\": \"遥测方式\"}, {\"optionCode\": \"C\", \"optionContent\": \"遥控方式\"}]','{\"correctAnswer\": \"C\"}','1、遥感方式：通过传感器被动接收目标信息（如卫星遥感），无法主动控制无人机。2、遥测方式：单向传输无人机状态数据（如速度、高度），无控制指令下发功能。3、遥控方式：通过无线通信实时发送控制指令并接收反馈，是飞行控制的核心技术。',1,90,'raw-bank/系统组成及介绍.docx#第90题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(78,NULL,2,'Q-SYSTEM-0092','single_choice','无人机控制站飞行摇杆常用操作方式是：','A','[{\"optionCode\": \"A\", \"optionContent\": \"姿态遥控\"}, {\"optionCode\": \"B\", \"optionContent\": \"舵面遥控\"}, {\"optionCode\": \"C\", \"optionContent\": \"自主控制\"}]','{\"correctAnswer\": \"A\"}','无人机控制站的飞行摇杆常用操作方式主要有三种：1、姿态遥控：通过摇杆直接控制无人机的姿态（如俯仰、滚转、偏航），是最常用的操作方式。2、舵面遥控：通过摇杆控制无人机的舵面角度，间接控制飞行姿态，较少使用。3、自主控制：无人机按照预设程序自主飞行，无需手动操作摇杆。',1,92,'raw-bank/系统组成及介绍.docx#第92题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(79,NULL,2,'Q-SYSTEM-0094','single_choice','（地面站）电子地图图元标注不包含下列哪种信息：','C','[{\"optionCode\": \"A\", \"optionContent\": \"场地标注\"}, {\"optionCode\": \"B\", \"optionContent\": \"警示标注\"}, {\"optionCode\": \"C\", \"optionContent\": \"地形标注\"}]','{\"correctAnswer\": \"C\"}','电子地图图元标注通常包含：场地标注（A）：标记特定区域或场地信息，如机场、起降点等。警示标志（B）：标注危险区域或需要注意的地点，如禁飞区、障碍物等。地形标注（C）：标注地形特征（如山脉、河流），但地面站电子地图更侧重功能性和人为信息，而非自然地形。',1,94,'raw-bank/系统组成及介绍.docx#第94题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(80,NULL,2,'Q-SYSTEM-0096','single_choice','导航子系统的功能是向无人机提供相对于所选定的参考坐标系的____引导无人机沿指定航线安全、准时、准确地飞 行。','A','[{\"optionCode\": \"A\", \"optionContent\": \"位置、速度、飞行姿态\"}, {\"optionCode\": \"B\", \"optionContent\": \"高度、速度、飞行姿态\"}, {\"optionCode\": \"C\", \"optionContent\": \"俯仰、滚转、偏航\"}]','{\"correctAnswer\": \"A\"}','导航子系统的主要功能是为无人机提供导航信息，确保其能沿预定航线飞行。这需要提供无人机的位置信息以确定其在空间中的确切地点，速度信息以控制飞行快慢，以及飞行姿态信息以调整飞行方向和角度。高度信息虽然重要，但不如位置信息全面；俯仰、滚转、偏航是飞行姿态的具体表现，不全面。',1,96,'raw-bank/系统组成及介绍.docx#第96题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(81,NULL,2,'Q-SYSTEM-0098','single_choice','校准地图时选取的标准点______','A','[{\"optionCode\": \"A\", \"optionContent\": \"不能在同一直线上\"}, {\"optionCode\": \"B\", \"optionContent\": \"不能在同一纬度上\"}, {\"optionCode\": \"C\", \"optionContent\": \"不能在同一经度上\"}]','{\"correctAnswer\": \"A\"}','地图校准需要选取分布合理的标准点：1、若标准点在同一直线上（A选项），会导致校准维度单一，无法准确确定地图的平面位置关系2、纬度相同（B选项）或经度相同（C选项）的点仍可提供有效的二维校准基准3、最佳实践是选取空间分布分散的点，避免线性排列',1,98,'raw-bank/系统组成及介绍.docx#第98题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(82,NULL,2,'Q-SYSTEM-0100','single_choice','无人机系统地面站不包括______','A','[{\"optionCode\": \"A\", \"optionContent\": \"机载电台\"}, {\"optionCode\": \"B\", \"optionContent\": \"无人机控制站\"}, {\"optionCode\": \"C\", \"optionContent\": \"载荷控制站\"}]','{\"correctAnswer\": \"A\"}','无人机系统地面站主要包括：1、无人机控制站：用于控制无人机的飞行。2、载荷控制站：用于控制无人机的任务设备（如摄像头、传感器等）。3、机载电台：安装在无人机上，用于与地面站通信，属于无人机的一部分，不属于地面站。因此，机载电台不属于地面站。',1,100,'raw-bank/系统组成及介绍.docx#第100题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(83,NULL,2,'Q-SYSTEM-0102','single_choice','某多旋翼飞行器螺旋桨标有“CW”字样，表面该螺旋桨','A','[{\"optionCode\": \"A\", \"optionContent\": \"俯视多旋翼飞行器顺时针旋翼\"}, {\"optionCode\": \"B\", \"optionContent\": \"俯视多旋翼飞行器逆时针旋翼\"}, {\"optionCode\": \"C\", \"optionContent\": \"该螺旋桨为“CW”牌\"}]','{\"correctAnswer\": \"A\"}','多旋翼飞行器领域，“CW”是常见标识。从俯视多旋翼飞行器的角度看，标有“CW”字样的螺旋桨是按照顺时针方向旋转的。选项B逆时针旋转不符合“CW”含义；选项C将“CW”简单理解为品牌，不符合专业常识。',1,102,'raw-bank/系统组成及介绍.docx#第102题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(84,NULL,2,'Q-SYSTEM-0104','single_choice','某螺旋桨是正桨，是指','C','[{\"optionCode\": \"A\", \"optionContent\": \"从多轴飞行器下方观看，该螺旋桨逆时针旋转\"}, {\"optionCode\": \"B\", \"optionContent\": \"从多轴飞行器上方观看，该螺旋桨顺时针旋转\"}, {\"optionCode\": \"C\", \"optionContent\": \"从多轴飞行器上方观看，该螺旋桨逆时针旋转\"}]','{\"correctAnswer\": \"C\"}','根据航空领域的定义，正桨是指从多轴飞行器上方观察，螺旋桨逆时针旋转。反桨则是从多轴飞行器上方观察，螺旋桨顺时针旋转。因此，选项C描述的是正桨的定义。',1,104,'raw-bank/系统组成及介绍.docx#第104题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(85,NULL,2,'Q-SYSTEM-0106','single_choice','八轴飞行器安装有','C','[{\"optionCode\": \"A\", \"optionContent\": \"8 个顺时针旋转螺旋桨\"}, {\"optionCode\": \"B\", \"optionContent\": \"2 个顺时针旋转螺旋桨，4 个逆时针旋转螺旋桨\"}, {\"optionCode\": \"C\", \"optionContent\": \"4 个顺时针旋转螺旋桨，4 个逆时针旋转螺旋桨\"}]','{\"correctAnswer\": \"C\"}','八轴飞行器为了保持平衡：1、需要对称配置正反方向旋转的螺旋桨2、如果全部顺时针或逆时针旋转，会产生巨大不平衡力矩3、最合理的配置是正反桨数量相等4、因此4个顺时针+4个逆时针是最稳定方案',1,106,'raw-bank/系统组成及介绍.docx#第106题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(86,NULL,2,'Q-SYSTEM-0108','single_choice','X 模式 4 轴飞行器，左前方的旋翼一般多为','A','[{\"optionCode\": \"A\", \"optionContent\": \"俯视顺时针旋转\"}, {\"optionCode\": \"B\", \"optionContent\": \"俯视逆时针旋转\"}, {\"optionCode\": \"C\", \"optionContent\": \"左视逆时针旋转\"}]','{\"correctAnswer\": \"A\"}','1、X模式4轴飞行器的旋翼布局特点是：对角线上的两个旋翼旋转方向相同相邻旋翼旋转方向相反2、俯视视角下：前方右侧和后方左侧旋翼同向旋转前方左侧和后方右侧旋翼同向旋转3、根据标准配置：通常设定为对角旋翼顺时针旋转因此左前方旋翼应为俯视顺时针旋转',1,108,'raw-bank/系统组成及介绍.docx#第108题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(87,NULL,2,'Q-SYSTEM-0110','single_choice','无人驾驶航空器系统必要的组成部分是','B','[{\"optionCode\": \"A\", \"optionContent\": \"飞行器平台、控制站\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞行器平台、控制站、通讯链路\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行器平台、通讯链路\"}]','{\"correctAnswer\": \"B\"}','无人驾驶航空器系统由以下必要部分组成：1、飞行器平台：执行飞行任务的主体2、控制站：用于操控和监控飞行器3、通讯链路：连接飞行器与控制站的通信通道这三个部分缺一不可，共同构成完整的无人驾驶航空器系统。',1,110,'raw-bank/系统组成及介绍.docx#第110题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(88,NULL,2,'Q-SYSTEM-0112','single_choice','轻小型无人机常用定距螺旋桨的尺寸通常用 X*Y 来表示，其中Y 代表','C','[{\"optionCode\": \"A\", \"optionContent\": \"桨径\"}, {\"optionCode\": \"B\", \"optionContent\": \"叶片数量\"}, {\"optionCode\": \"C\", \"optionContent\": \"螺距\"}]','{\"correctAnswer\": \"C\"}','在轻小型无人机领域，定距螺旋桨的尺寸常用X*Y格式表示。其中X代表桨径，即螺旋桨旋转形成的圆的直径；Y代表螺距，即螺旋桨旋转一周前进的理论距离。叶片数量通常不在此标注中体现。',1,112,'raw-bank/系统组成及介绍.docx#第112题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(89,NULL,2,'Q-SYSTEM-0114','single_choice','外转子电机规格 2208；9T；KV1000 分别代表什么含义','A','[{\"optionCode\": \"A\", \"optionContent\": \"定子线圈的直径 22 毫米，定子线圈的高度 8 毫米，每伏特电压能达到的每分钟转速为 1000 转\"}, {\"optionCode\": \"B\", \"optionContent\": \"定子线圈的直径 22 英寸，定子线圈的高度 8 英寸，每伏特电压能达到的每分钟转速为 1000 转\"}, {\"optionCode\": \"C\", \"optionContent\": \"定子线圈的直径 22 英寸，定子线圈的高度 8 英寸，每分钟转速为 1000 转\"}]','{\"correctAnswer\": \"A\"}','1、\"2208\"规格：前两位\"22\"表示定子线圈直径为22毫米后两位\"08\"表示定子线圈高度为8毫米2、\"KV1000\"参数：表示每伏特电压能达到的每分钟转速为1000转这是电机的重要性能参数3、单位说明：电机规格通常使用毫米作为单位英寸单位不符合行业惯例',1,114,'raw-bank/系统组成及介绍.docx#第114题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(90,NULL,2,'Q-SYSTEM-0116','single_choice','以下地面链路天线哪一种是定向天线','A','[{\"optionCode\": \"A\", \"optionContent\": \"八木天线\"}, {\"optionCode\": \"B\", \"optionContent\": \"三叶草天线\"}, {\"optionCode\": \"C\", \"optionContent\": \"鞭状天线\"}]','{\"correctAnswer\": \"A\"}','1、八木天线：是一种定向天线，常用于需要高方向性和增益的场景，如无线通信、电视接收等。2、三叶草天线：是一种全向天线，辐射能量均匀分布在各个方向，常用于需要全方位覆盖的场景。3、鞭状天线：也是一种全向天线，常用于移动通信设备，如手机、对讲机等。',1,116,'raw-bank/系统组成及介绍.docx#第116题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(91,NULL,2,'Q-SYSTEM-0118','single_choice','_____传感器是飞行控制系统的基本传感器之一，用以改善系统的阻尼特性、提高稳定性_','B','[{\"optionCode\": \"A\", \"optionContent\": \"空速\"}, {\"optionCode\": \"B\", \"optionContent\": \"角速率\"}, {\"optionCode\": \"C\", \"optionContent\": \"迎角、侧滑角\"}]','{\"correctAnswer\": \"B\"}','飞行控制系统需要多种传感器来获取飞行状态信息。其中：空速传感器主要用于测量飞机的空速，对飞行控制有重要作用，但不是直接改善阻尼特性的主要传感器。角速率传感器用于测量飞机的旋转速率（如俯仰、滚转和偏航速率），能够直接反馈飞机的动态变化，从而改善系统的阻尼特性和提高稳定性。迎角、侧滑角传感器用于测量飞机的迎角和侧滑角，主要用于飞行姿态控制，但对阻尼特性的改善作用不如角速率传感器直接。因此，角速率传感器是飞行控制系统中用于改善阻尼特性和提高稳定性的基本传感器之一。',1,118,'raw-bank/系统组成及介绍.docx#第118题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(92,NULL,2,'Q-SYSTEM-0120','single_choice','多轴飞行器航空摄影中， 日出日落拍摄时，摄像机白平衡调整应调整为_______以拍出正常白平衡画面','B','[{\"optionCode\": \"A\", \"optionContent\": \"高色温值\"}, {\"optionCode\": \"B\", \"optionContent\": \"低色温值\"}, {\"optionCode\": \"C\", \"optionContent\": \"闪光灯模式\"}]','{\"correctAnswer\": \"B\"}','1、日出日落的光线特点：日出日落时，阳光斜射，光线穿过大气层的路径较长，蓝光被散射较多，剩余光线偏红，色温较低（约2000-3500K）。2、白平衡的作用：白平衡用于校正不同色温下的色彩偏差，使白色物体在不同光线下仍呈现白色。3、调整方法：当环境色温较低时，需将摄像机的白平衡设置为更低的色温值（即“暖色调”模式），以补偿环境光的偏红现象，使画面色彩还原正常。',1,120,'raw-bank/系统组成及介绍.docx#第120题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(93,NULL,2,'Q-SYSTEM-0122','single_choice','以多轴航拍飞行器为例，是否轴数越多载重能力越大','C','[{\"optionCode\": \"A\", \"optionContent\": \"是\"}, {\"optionCode\": \"B\", \"optionContent\": \"不是\"}, {\"optionCode\": \"C\", \"optionContent\": \"不一定\"}]','{\"correctAnswer\": \"C\"}','多轴航拍飞行器的载重能力不仅取决于轴数，还与电机功率、电池性能、螺旋桨效率等因素密切相关。轴数增加可能带来更稳定的飞行，但不一定直接提升载重能力。因此，轴数越多载重能力越大的说法并不准确。',1,122,'raw-bank/系统组成及介绍.docx#第122题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(94,NULL,2,'Q-SYSTEM-0124','single_choice','对于多轴航拍飞行器云台说法正确的是','B','[{\"optionCode\": \"A\", \"optionContent\": \"云台保证无人机在云层上飞行的安全\"}, {\"optionCode\": \"B\", \"optionContent\": \"云台是航拍设备的增稳和操纵装置\"}, {\"optionCode\": \"C\", \"optionContent\": \"云台的效果和传统舵机一样\"}]','{\"correctAnswer\": \"B\"}','A选项：云台保证无人机在云层上飞行的安全。这个说法不正确，云台的主要功能不是保证飞行安全，而是稳定航拍设备。B选项：云台是航拍设备的增稳和操纵装置。这个说法正确，云台通过电机和控制系统，保持航拍设备的稳定，确保拍摄画面的清晰和稳定。C选项：云台的效果和传统舵机一样。这个说法不正确，云台和传统舵机的功能和应用场景不同，云台主要用于航拍设备的稳定，而舵机多用于机械控制。',1,124,'raw-bank/系统组成及介绍.docx#第124题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(95,NULL,2,'Q-SYSTEM-0126','single_choice','使用多轴飞行器，航拍过程中，为了保证画面明暗稳定，相机尽量设定为','C','[{\"optionCode\": \"A\", \"optionContent\": \"光圈固定\"}, {\"optionCode\": \"B\", \"optionContent\": \"快门固定\"}, {\"optionCode\": \"C\", \"optionContent\": \"ISO 固定\"}]','{\"correctAnswer\": \"C\"}','1、光圈固定(A)：控制进光量大小，但改变光圈会影响景深，且环境光线变化时光圈固定可能导致曝光不稳定。2、快门固定(B)：控制曝光时间，但环境光线变化时快门固定可能导致过曝或欠曝。3、ISO固定(C)：控制传感器感光度，固定ISO配合自动调整光圈/快门能保持曝光稳定，是航拍保证明暗稳定的最佳选择。',1,126,'raw-bank/系统组成及介绍.docx#第126题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(96,NULL,2,'Q-SYSTEM-0128','single_choice','视距外运行使用自主模式的无人机，出现无人机失控的情况，机长应该执行相应的预案，包括：①无人机应急回 收程序; ②对于接入无人机云的用户，应在系统内上报相关情况;③对于未接入无人机云的用户，联系相关空管服务 部门的程序，上报遵照以上程序的相关责任人名单。','A','[{\"optionCode\": \"A\", \"optionContent\": \"①②③\"}, {\"optionCode\": \"B\", \"optionContent\": \"②③\"}, {\"optionCode\": \"C\", \"optionContent\": \"①③\"}]','{\"correctAnswer\": \"A\"}','1、无人机应急回收程序（①）：失控时首要执行，最大限度保障安全。2、接入无人机云的用户（②）：需通过系统上报情况，便于追踪管理。3、未接入无人机云的用户（③）：需直接联系空管部门，人工上报责任人名单。根据参考资料，三个步骤均为必须执行的预案内容。',1,128,'raw-bank/系统组成及介绍.docx#第128题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(97,NULL,2,'Q-SYSTEM-0130','single_choice','多轴飞行器飞行时，使用哪种模式，飞行前向和主控记录的某一时刻机头朝向一致（）','C','[{\"optionCode\": \"A\", \"optionContent\": \"GPS 模式\"}, {\"optionCode\": \"B\", \"optionContent\": \"返航点锁定\"}, {\"optionCode\": \"C\", \"optionContent\": \"航向锁定\"}]','{\"correctAnswer\": \"C\"}','GPS模式主要用于定位和导航，不直接控制机头朝向与记录一致。返航点锁定是让飞行器回到设定的返航点，也不确保飞行前向和记录机头朝向一致。航向锁定模式会使飞行器按照记录的某一时刻机头朝向进行飞行，保证飞行方向和主控记录的某一时刻机头朝向一致。',1,130,'raw-bank/系统组成及介绍.docx#第130题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(98,NULL,2,'Q-SYSTEM-0132','single_choice','下面哪些是有记忆效应的电池','B','[{\"optionCode\": \"A\", \"optionContent\": \"Lipo\"}, {\"optionCode\": \"B\", \"optionContent\": \"NiMH\"}, {\"optionCode\": \"C\", \"optionContent\": \"LiFe\"}]','{\"correctAnswer\": \"B\"}','1、Lipo（锂聚合物电池）：无记忆效应，可随充随放。2、NiMH（镍氢电池）：有轻微记忆效应，需定期完全放电维护。3、LiFe（磷酸铁锂电池）：无记忆效应，循环寿命长。',1,132,'raw-bank/系统组成及介绍.docx#第132题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(99,NULL,2,'Q-SYSTEM-0134','single_choice','不适合作为无人机机体材料的是','C','[{\"optionCode\": \"A\", \"optionContent\": \"碳纤维\"}, {\"optionCode\": \"B\", \"optionContent\": \"玻璃纤维\"}, {\"optionCode\": \"C\", \"optionContent\": \"工程塑料\"}]','{\"correctAnswer\": \"C\"}','1、碳纤维：轻质、高强度、耐疲劳，是无人机常用材料，适合用作机体材料。2、玻璃纤维：强度较高，但重量较大，耐候性一般，可作为备选材料，但不是最理想选择。3、工程塑料：重量轻，但强度和耐高温性能较差，不适合承受无人机飞行中的高应力环境。答案总结最不适合作为无人机机体材料的是 C. 工程塑料，因其强度和耐高温性能不足。',1,134,'raw-bank/系统组成及介绍.docx#第134题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(100,NULL,2,'Q-SYSTEM-0136','single_choice','民用无人机常使用的小松 G260 是（ ）发动机','A','[{\"optionCode\": \"A\", \"optionContent\": \"二冲程汽油\"}, {\"optionCode\": \"B\", \"optionContent\": \"四冲程汽油\"}, {\"optionCode\": \"C\", \"optionContent\": \"四冲程柴油\"}]','{\"correctAnswer\": \"A\"}','选项分析：A、二冲程汽油：结构简单、重量轻，适合无人机对动力的轻量化需求。B、四冲程汽油：效率更高但结构复杂，无人机较少采用。C、四冲程柴油：笨重且点火方式不适合无人机。',1,136,'raw-bank/系统组成及介绍.docx#第136题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(101,NULL,2,'Q-SYSTEM-0138','single_choice','二冲程与四冲程发动机相比的主要优点','C','[{\"optionCode\": \"A\", \"optionContent\": \"耗油率\"}, {\"optionCode\": \"B\", \"optionContent\": \"重量轻\"}, {\"optionCode\": \"C\", \"optionContent\": \"功率重量比高\"}]','{\"correctAnswer\": \"C\"}','二冲程发动机的工作循环包括进气、压缩、做功和排气四个过程，但它在两个行程内完成，因此做功频率更高。这使得二冲程发动机在相同排量下能产生更高的功率，从而具有更高的功率重量比。相比之下，四冲程发动机虽然效率更高、排放更清洁，但在功率重量比上不如二冲程发动机。',1,138,'raw-bank/系统组成及介绍.docx#第138题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(102,NULL,2,'Q-SYSTEM-0140','single_choice','活塞式发动机中，CDI 系统属于 ( ) 的一部分','C','[{\"optionCode\": \"A\", \"optionContent\": \"进气系统\"}, {\"optionCode\": \"B\", \"optionContent\": \"排气系统\"}, {\"optionCode\": \"C\", \"optionContent\": \"点火系统\"}]','{\"correctAnswer\": \"C\"}','1、CDI系统功能：通过电容器储存能量并瞬间释放高压电，产生电火花点燃气缸内混合气体2、系统归属：点火系统负责燃料燃烧的触发，而进气/排气系统分别管理气流进出，与点火无关。3、排除法：A（进气）、B（排气）均与电火花无关，直接锁定C选项。',1,140,'raw-bank/系统组成及介绍.docx#第140题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(103,NULL,2,'Q-SYSTEM-0142','single_choice','目前民用无人机多用到的舵机属于哪种伺服执行机构类型','A','[{\"optionCode\": \"A\", \"optionContent\": \"电动伺服执行机构\"}, {\"optionCode\": \"B\", \"optionContent\": \"电液伺服执行机构\"}, {\"optionCode\": \"C\", \"optionContent\": \"气动伺服执行机构\"}]','{\"correctAnswer\": \"A\"}','1、电动伺服执行机构：以电动机为动力源，通过电信号控制转角或位移，具有体积小、响应快、控制精度高的特点，非常适合民用无人机对重量和响应速度的要求。2、电液伺服执行机构：依赖液压系统，虽输出力大但体积笨重、维护复杂，多用于大型工业设备或军用领域，民用无人机极少采用。3、气动伺服执行机构：以压缩空气为动力，存在响应延迟和气压稳定性问题，且需额外气源装置，不适用于无人机轻量化设计。结论：民用无人机舵机普遍选用电动伺服执行机构。',1,142,'raw-bank/系统组成及介绍.docx#第142题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(104,NULL,2,'Q-SYSTEM-0144','single_choice','位置传感器用于感受无人机的位置，是飞行轨迹控制的必要前提。 ( ) 是典型的位置传感器。','C','[{\"optionCode\": \"A\", \"optionContent\": \"角速率传感器\"}, {\"optionCode\": \"B\", \"optionContent\": \"加速度传感器\"}, {\"optionCode\": \"C\", \"optionContent\": \"GPS 卫星导航接收机\"}]','{\"correctAnswer\": \"C\"}','1、角速率传感器：用于测量无人机的旋转速率，属于姿态传感器，不能直接获取位置信息。2、加速度传感器：用于测量无人机的加速度，通过积分可间接估算位置，但存在累积误差，不是典型的位置传感器。3、GPS卫星导航接收机：通过接收卫星信号直接获取无人机的经纬度位置信息，是典型的位置传感器。',1,144,'raw-bank/系统组成及介绍.docx#第144题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(105,NULL,2,'Q-SYSTEM-0146','single_choice','电调是多旋翼无人机最重要的部件之一，不属于飞行器电调功能的是：','C','[{\"optionCode\": \"A\", \"optionContent\": \"变压供电\"}, {\"optionCode\": \"B\", \"optionContent\": \"电机调速\"}, {\"optionCode\": \"C\", \"optionContent\": \"实时电机反转\"}]','{\"correctAnswer\": \"C\"}','1、选项A：飞行器状态（如高度、速度）、链路（通信质量）和载荷状态（如相机工作状态）是地面站的核心显示内容，直接影响飞行操作。2、选项B：飞行空域信息通常由导航系统或规划软件提供，非地面站显示系统的直接功能。3、选项C：无人机飞行员状态（如生理指标）与地面站无关，属于飞行员自身监测范畴。根据无人机系统设计原则，地面站需优先保障飞行器实时数据监控，故选A。',1,146,'raw-bank/系统组成及介绍.docx#第146题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(106,NULL,2,'Q-SYSTEM-0148','single_choice','哪些是无人机的飞行模式：','A','[{\"optionCode\": \"A\", \"optionContent\": \"指令控制\"}, {\"optionCode\": \"B\", \"optionContent\": \"陀螺控制\"}, {\"optionCode\": \"C\", \"optionContent\": \"载荷控制\"}]','{\"correctAnswer\": \"A\"}','无人机的飞行模式通常包括：指令控制：通过遥控器或地面站发送指令控制无人机飞行。陀螺控制：利用陀螺仪稳定无人机姿态，属于飞行控制的一部分。载荷控制：通常指对无人机搭载设备的控制，不属于飞行模式。因此，指令控制和陀螺控制属于无人机的飞行模式，而载荷控制不属于。',1,148,'raw-bank/系统组成及介绍.docx#第148题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(107,NULL,3,'Q-ATC-0002','single_choice','下面哪个单位领导全国的飞行管制工作[1分]','C','[{\"optionCode\": \"A\", \"optionContent\": \"国务院\"}, {\"optionCode\": \"B\", \"optionContent\": \"民航局\"}, {\"optionCode\": \"C\", \"optionContent\": \"国务院﹑中央军委空中交通管制委员会\"}]','{\"correctAnswer\": \"C\"}','根据《中华人民共和国飞行基本规则》，全国飞行管制工作由国务院、中央军事委员会空中交通管制委员会（简称“国家空管委”）统一领导。该委员会负责统筹协调全国范围内的飞行管制事务，涵盖军用和民用航空管理。‌‌‌‌‌‌中国人民解放军空军‌负责境内飞行管制的具体组织实施，各军区空军均设有空中管制中心，处理临时起降点及特殊空域飞行申请。‌‌‌中国民用航空局空中交通管理局‌负责民用航空的空中交通服务、通信导航等职能，但无权领导全国飞行管制工作。',1,2,'raw-bank/空中交通管制.docx#第2题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(108,NULL,3,'Q-ATC-0004','single_choice','执行紧急救护、抢险救灾或者其它紧急任务，飞行计划申请最迟应在飞行前__提出。[1分]','B','[{\"optionCode\": \"A\", \"optionContent\": \"30 分钟\"}, {\"optionCode\": \"B\", \"optionContent\": \"一小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"二小时\"}]','{\"correctAnswer\": \"B\"}','为了保证飞行任务的及时性和有效性，飞行计划申请需要在飞行前足够的时间内提出，以便相关部门能够进行必要的准备和协调。根据相关规定，执行紧急救护、抢险救灾或其他紧急任务的飞行计划申请最迟应在飞行前一小时提出，以便相关部门有足够的时间进行审批和安排，确保飞行任务能够顺利进行。',1,4,'raw-bank/空中交通管制.docx#第4题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(109,NULL,3,'Q-ATC-0006','single_choice','关于飞行管理不正确的是[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"在一个划定的管制空域内，可由两个空中交通管制单位负责空中交通管制\"}, {\"optionCode\": \"B\", \"optionContent\": \"通常情况下，民用航空器不得飞入禁区和限制区\"}, {\"optionCode\": \"C\", \"optionContent\": \"民用航空器未经批准不得飞出中华人民共和国领空\"}]','{\"correctAnswer\": \"A\"}','A根据《飞行管理规则》，划定的管制空域通常由单一空中交通管制单位负责，以避免指令冲突。‌‌B民用航空器严格禁止进入禁区和限制区。C未经批准，任何航空器不得飞出中华人民共和国领空或让境外民用航空器未经批准进入我国领空。‌‌',1,6,'raw-bank/空中交通管制.docx#第6题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(110,NULL,3,'Q-ATC-0008','single_choice','民用航空器在管制空域内飞行[1分]','C','[{\"optionCode\": \"A\", \"optionContent\": \"可以自由飞行\"}, {\"optionCode\": \"B\", \"optionContent\": \"可以按 VF 自由飞行\"}, {\"optionCode\": \"C\", \"optionContent\": \"必须取得空中交通管制单位的许可\"}]','{\"correctAnswer\": \"C\"}','A管制空域不允许自由飞行，否则会造成空中交通混乱和安全隐患。B\"VF\"（目视飞行规则）仅适用于非管制空域或特定条件下，即使在目视飞行时，管制空域内仍需取得许可。C根据国际和各国航空法规，管制空域内飞行必须提前取得空中交通管制单位的许可，以协调飞行活动并保障安全。',1,8,'raw-bank/空中交通管制.docx#第8题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(111,NULL,3,'Q-ATC-0010','single_choice','民用航空器因故确需偏离指定的航路或改变飞行高度飞行时，应当首先______管制[1分]','C','[{\"optionCode\": \"A\", \"optionContent\": \"得到机长的允许\"}, {\"optionCode\": \"B\", \"optionContent\": \"取得机组的一致同意\"}, {\"optionCode\": \"C\", \"optionContent\": \"取得空中交通管制单位的许可\"}]','{\"correctAnswer\": \"C\"}','A民用航空器在飞行过程中，机长虽然对飞机的运行有最终的决策权，但在改变航路或飞行高度前，必须先得到空中交通管制单位的许可。这是为了确保飞行计划的变更不会影响其他航空器的飞行安全和空域的有序管理。B机组成员的一致同意虽然重要，但并不是改变航路或飞行高度的首要条件，因为机组成员的意见并不能代表对整体空中交通情况的全面了解。C空中交通管制单位负责管理和协调所有在空中的飞行活动，确保飞行安全和效率，因此任何航路的改变或高度的调整都需要经过他们的许可。',1,10,'raw-bank/空中交通管制.docx#第10题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(112,NULL,3,'Q-ATC-0012','single_choice','航空器与 ATC 进行第一次无线联络时，应当首先呼叫[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"所需联系的 ATC 的名称\"}, {\"optionCode\": \"B\", \"optionContent\": \"航空器的注册号\"}, {\"optionCode\": \"C\", \"optionContent\": \"航空器的机型\"}]','{\"correctAnswer\": \"A\"}','A航空器与ATC进行第一次无线电联络时，首先应当呼叫所需联系的ATC的名称，以确认对方的身份和确保通信对象正确。这是为了确保航空器与正确的空中交通管制单位建立联系，避免与其他管制单位混淆。B接下来，航空器需要报告自己的注册号，以便ATC识别和确认该航空器的身份。C最后，航空器可能会报告其他相关信息，如机型等，但这不是第一次呼叫时的首要内容。',1,12,'raw-bank/空中交通管制.docx#第12题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(113,NULL,3,'Q-ATC-0014','single_choice','在一个划定的管制空域内，由________负责该空域内的航空器的空中交通管制[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"军航或民航的一个空中交通管制单位\"}, {\"optionCode\": \"B\", \"optionContent\": \"军航和民航的各一个空中交通管制单位\"}, {\"optionCode\": \"C\", \"optionContent\": \"军航的一个空中交通管制单位\"}]','{\"correctAnswer\": \"A\"}','民航管辖场景‌：民航航路、机场终端区等民用航空活动集中区域，由民航管制单位主导管理。‌‌‌军航管辖场景‌：军事训练区、防空识别区等专用空域，由军航管制单位负责。A每个管制空域只能由一个空中交通管制单位负责，确保指令的唯一性和飞行安全。该原则既符合国际民航组织（ICAO）规定，也体现在《民用航空空中交通管理规则》中。B可能导致指令冲突，违背空域管理唯一性原则。‌‌C忽略民航实际管辖场景，不符合军民融合空域管理现状。',1,14,'raw-bank/空中交通管制.docx#第14题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(114,NULL,3,'Q-ATC-0016','single_choice','在下列哪种情况下民用航空器可以飞越城市上空[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"指定的航路必需飞越城市上空时\"}, {\"optionCode\": \"B\", \"optionContent\": \"能见地标的目视飞行时\"}, {\"optionCode\": \"C\", \"optionContent\": \"夜间飞行时\"}]','{\"correctAnswer\": \"A\"}','A当民航器沿空中交通管理部门规划的固定航路飞行，且该航路必须经过城市上空时（如机场进出港必经航路），可在航行管制许可下合法飞越。航空器在起降过程中确需飞越城市上空时，允许临时调整飞行路径‌。经国家规定的程序（如空中交通管制单位许可、紧急救援任务审批等）批准后，可豁免一般性限制。B目视飞行规则要求避开人口稠密区，仅有能见地标不足以构成合法飞越城市的依据。C夜间飞行仍需遵守航路和高度限制，时间因素本身不构成例外条件。',1,16,'raw-bank/空中交通管制.docx#第16题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(115,NULL,3,'Q-ATC-0018','single_choice','飞行申请的内容包括[1分]','B','[{\"optionCode\": \"A\", \"optionContent\": \"任务性质．航空器型别．装载情况．飞行范围．起止时间．飞行高度和飞行条件\"}, {\"optionCode\": \"B\", \"optionContent\": \"任务性质．航空器型别．飞行范围．起止时间．飞行高度和飞行条件\"}, {\"optionCode\": \"C\", \"optionContent\": \"任务性质．航空器型别．装载情况．起止时间．飞行高度和飞行条件\"}]','{\"correctAnswer\": \"B\"}','任务性质：明确飞行任务的性质和目的。航空器型别：指明所使用的航空器类型。飞行范围：说明飞行的区域和航线。起止时间：包括飞行的开始和结束时间。飞行高度：指明飞行的高度。飞行条件：包括气象条件和其他飞行环境因素。这些信息是飞行申请中必须包含的基本内容，以确保飞行计划的顺利实施和飞行安全。装载情况虽然也是重要的信息，但在飞行申请中并不是必须的内容。',1,18,'raw-bank/空中交通管制.docx#第18题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(116,NULL,3,'Q-ATC-0020','single_choice','航空器使用航路和航线，应当经______同意[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"负责该航路和航线的飞行管制部门\"}, {\"optionCode\": \"B\", \"optionContent\": \"空中交通管理局下属的区域管制部门\"}, {\"optionCode\": \"C\", \"optionContent\": \"中国人民解放军空军\"}]','{\"correctAnswer\": \"A\"}','A引用《中华人民共和国飞行基本规则》（国务院、中央军事委员会令第405号）第六十四条的相关规定，明确规定航空器使用航路和航线必须经\"负责该航路和航线的飞行管制部门\"同意。B虽然空中交通管理局及其下属机构也参与空中交通管理，但具体到航路和航线的使用授权，则是由直接负责这些航路和航线的飞行管制部门来决定。C而中国人民解放军空军的主要职责通常涉及国防和军队飞行活动，不一定直接管理民用或其他非军事飞行的航路和航线使用。',1,20,'raw-bank/空中交通管制.docx#第20题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(117,NULL,3,'Q-ATC-0022','single_choice','空域是航空器运行的环境，也是宝贵的国家资源。国务院、中央军委十分重视我国民用航空交通管制的建设工作， 目前正在推进空域管理改革，预计划分三类空域，为____。[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"管制空域、监视空域和报告空域\"}, {\"optionCode\": \"B\", \"optionContent\": \"管制空域、非管制空域和报告空域\"}, {\"optionCode\": \"C\", \"optionContent\": \"管制空域、非管制空域和特殊空域\"}]','{\"correctAnswer\": \"A\"}','据国务院、中央军委对民用航空交通管制的建设规划，旨在通过划分不同空域类别来优化航空器运行环境，提升管理效率。‌管制空域‌：需严格遵守飞行规则和权限管理。‌监视空域‌：需持续监控飞行动态。‌报告空域‌：需按规定报告飞行计划。',1,22,'raw-bank/空中交通管制.docx#第22题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(118,NULL,3,'Q-ATC-0024','single_choice','中华人民共和国境内的飞行管制[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"由中国人民解放军空军统一组织实施，各有关飞行管制部门按照各自的职责分工提供空中交通管制服务\"}, {\"optionCode\": \"B\", \"optionContent\": \"由国务院﹑中央军委空中交通管制委员会统一组织实施，各有关飞行管制部门按照各自的职责分工提供空中交通管 制服务\"}, {\"optionCode\": \"C\", \"optionContent\": \"由中国民用航空总局空中交通管理局统一组织实施，各有关飞行管制部门按照各自的职责分工提供空中交通管制服 务\"}]','{\"correctAnswer\": \"A\"}','根据第二十八条的规定，中华人民共和国境内的飞行管制由中国人民解放军空军统一组织实施。这意味着空军在飞行管制中起到主导作用，负责整体的协调和管理。各有关飞行管制部门则按照各自的职责分工提供具体的空中交通管制服务，确保飞行活动的有序进行。',1,24,'raw-bank/空中交通管制.docx#第24题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(119,NULL,3,'Q-ATC-0026','single_choice','在飞行任务书中，应当明确[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"飞行任务．起飞时间．航线．高度．允许机长飞行的最低气象条件以及其他有关事项\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞行任务．机组成员﹑起飞时间．航线．高度．允许机长飞行的最低气象条件以及其他有关事项\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行任务．起飞时间．航线．允许机长飞行的最低气象条件以及其他有关事项\"}]','{\"correctAnswer\": \"A\"}','飞行任务书是许可飞行人员进行转场飞行和民用航空飞行的基本文件‌，其签发机构明确如下：飞行任务书由驻机场航空单位或航空公司的负责人签发。若为军用航空器，则由驻机场航空单位的负责人签发；若为民用航空器，则由航空公司负责人签发。‌‌‌核心内容要求‌:任务书中需明确飞行任务、起飞时间、航线、高度、最低气象条件等关键事项。签发后，飞行人员需严格遵守任务书规定，服从空中交通管制指令。该文件适用于所有转场飞行和民用航空飞行活动，确保飞行安全与合规性。',1,26,'raw-bank/空中交通管制.docx#第26题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(120,NULL,3,'Q-ATC-0028','single_choice','为保障飞行安全，建议无论是在白天还是夜间,当发动机在运转时就打开：[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"防撞灯\"}, {\"optionCode\": \"B\", \"optionContent\": \"着陆灯\"}, {\"optionCode\": \"C\", \"optionContent\": \"航行灯\"}]','{\"correctAnswer\": \"A\"}','A防撞灯的典型特征是红色旋转灯或白色频闪灯，其核心作用是提醒周围人员与飞机注意发动机运行状态，避免碰撞风险。B着陆灯主要用于起飞和降落阶段的跑道照明。C航行灯则是标示飞机位置和方向的红绿白色固定灯，通常在飞机移动时开启。',1,28,'raw-bank/空中交通管制.docx#第28题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(121,NULL,3,'Q-ATC-0030','single_choice','航空器进行空域飞行时，应当按照规定的______进入空域或者脱离空域，并且保持在规定的空域和高度范围内飞 行[1分]','B','[{\"optionCode\": \"A\", \"optionContent\": \"航线（航向）、高度、次序和进出点\"}, {\"optionCode\": \"B\", \"optionContent\": \"航线（航向）、高度、次序\"}, {\"optionCode\": \"C\", \"optionContent\": \"航线（航向）、高度\"}]','{\"correctAnswer\": \"B\"}','航空器在进入或脱离空域时，需要按照规定的航线（航向）飞行，以确保飞行路径的明确和有序。飞行高度是确保不同航空器之间安全的重要因素，必须严格按照规定的高度飞行，以避免碰撞。飞行次序是指航空器在空域中的飞行顺序和时间安排，以避免空中交通拥堵和冲突。',1,30,'raw-bank/空中交通管制.docx#第30题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(122,NULL,3,'Q-ATC-0032','single_choice','微型无人机是指[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"空机质量小于等于 7kg 的无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"质量小于 7kg 的无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"质量小于等于 7kg 的无人机\"}]','{\"correctAnswer\": \"A\"}','无人机类别 空机质量范围微型无人机 0kg(不含)＜微型≤7kg(含)轻型无人机 7kg(不含)＜轻型≤116kg(含)小型无人机 116kg(不含)＜小型≤5700kg(含)大型无人机 5700kg(不含)＜大型',1,32,'raw-bank/空中交通管制.docx#第32题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(123,NULL,3,'Q-ATC-0034','single_choice','大型无人机是指[1分]','A','[{\"optionCode\": \"A\", \"optionContent\": \"空机质量大于 5700 千克的无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"质量大于 5700 千克的无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"空机质量大于等于 5700 千克的无人机\"}]','{\"correctAnswer\": \"A\"}','无人机类别 空机质量范围微型无人机 0kg(不含)＜微型≤7kg(含)轻型无人机 7kg(不含)＜轻型≤116kg(含)小型无人机 116kg(不含)＜小型≤5700kg(含)大型无人机 5700kg(不含)＜大型',1,34,'raw-bank/空中交通管制.docx#第34题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(124,NULL,3,'Q-ATC-0036','single_choice','仪表（云中）飞行空域的边界距离航路、空中走廊以及其他空域的边界，不得小于[1分]','B','[{\"optionCode\": \"A\", \"optionContent\": \"5 公里\"}, {\"optionCode\": \"B\", \"optionContent\": \"10 公里\"}, {\"optionCode\": \"C\", \"optionContent\": \"15 公里\"}]','{\"correctAnswer\": \"B\"}','A数值过小，不符合仪表飞行对安全间隔的严格要求。通常目视飞行规则的间隔可能较低，但仪表飞行需更大余度。B符合法规要求。例如《飞行基本规则》附件二明确，仪表飞行空域边界与航路、空中走廊等边界的最小横向间隔为10公里，确保规避飞行冲突。C无依据支持此数值。',1,36,'raw-bank/空中交通管制.docx#第36题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(125,NULL,4,'Q-FMR-0001','single_choice','无人机制造商编写的随机文档（无人机所有者/信息手册）__________。','C','[{\"optionCode\": \"A\", \"optionContent\": \"可以替代《无人机飞行手册》\"}, {\"optionCode\": \"B\", \"optionContent\": \"一般情况下可以替代《无人机飞行手册》\"}, {\"optionCode\": \"C\", \"optionContent\": \"不可替代《无人机飞行手册》\"}]','{\"correctAnswer\": \"C\"}','根据中国民用航空相关规定，无人机操作需严格遵循《无人机飞行手册》指导，该手册由局方批准并包含飞行操作规范、维护标准等核心内容。制造商提供的《无人机所有者/信息手册》属于辅助性文件，主要包含设备参数、用户指南等信息，无法替代局方批准的飞行手册。',1,1,'raw-bank/无人机飞行手册、法律法规及其他.docx#第1题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(126,NULL,4,'Q-FMR-0003','single_choice','无人机制造商编写的随机文档《无人机所有者/信息手册》。','B','[{\"optionCode\": \"A\", \"optionContent\": \"需经局方批准\"}, {\"optionCode\": \"B\", \"optionContent\": \"不需局方批准\"}, {\"optionCode\": \"C\", \"optionContent\": \"特殊飞行器需局方批准\"}]','{\"correctAnswer\": \"B\"}','根据民航规章的要求，无人机制造商编写的《无人机所有者/信息手册》属于制造商为用户提供的操作指南和基本信息文档，主要用于指导用户安全使用和维护无人机。此类文件通常属于制造商的自主责任范畴，不需要向局方（如中国民航局）提交审批。',1,3,'raw-bank/无人机飞行手册、法律法规及其他.docx#第3题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(127,NULL,4,'Q-FMR-0005','single_choice','无人机飞行前，无人机飞行员','A','[{\"optionCode\": \"A\", \"optionContent\": \"按照随机《无人机飞行手册》指导飞行\"}, {\"optionCode\": \"B\", \"optionContent\": \"按照积累的经验指导飞行\"}, {\"optionCode\": \"C\", \"optionContent\": \"重点参考《无人机所有者/信息手册》\"}]','{\"correctAnswer\": \"A\"}','根据无人机操作规范和安全要求，飞行员在飞行前必须严格遵循随机附带的《无人机飞行手册》进行准备工作。该手册包含制造商针对特定机型制定的飞行前检查清单、操作流程及安全注意事项，是确保飞行合法性和安全性的核心依据。\nB个人经验可能忽略特定机型的技术细节或最新法规，存在安全隐患。\nC所有者手册参考通常侧重设备维护而非实时飞行操作，无法替代飞行手册的针对性指导。',1,5,'raw-bank/无人机飞行手册、法律法规及其他.docx#第5题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(128,NULL,4,'Q-FMR-0007','single_choice','无人机系统无线电资源的使用______局方无线电管理部门的许可证。','A','[{\"optionCode\": \"A\", \"optionContent\": \"需要\"}, {\"optionCode\": \"B\", \"optionContent\": \"不需要\"}, {\"optionCode\": \"C\", \"optionContent\": \"一般情况下不需要\"}]','{\"correctAnswer\": \"A\"}','使用无线电频率需取得许可，无人机系统作为无线电台（站）的一部分，其无线电资源的使用属于法定监管范畴。‌‌\n若无人机仅用于本地控制（如视距内飞行），且未涉及远程数据传输等跨区域通信，可能无需单独申请频率许可（但需符合微功率短距离设备的规定）。‌‌\n常规情况下，涉及数据链通信的无人机需通过局方许可确保频谱合规性。',1,7,'raw-bank/无人机飞行手册、法律法规及其他.docx#第7题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(129,NULL,4,'Q-FMR-0009','single_choice','民用无人机驾驶航空器系统驾驶员合格证由那个部门颁发','B','[{\"optionCode\": \"A\", \"optionContent\": \"民航局下属局（局）\"}, {\"optionCode\": \"B\", \"optionContent\": \"中国航空器拥有者及驾驶员协会\"}, {\"optionCode\": \"C\", \"optionContent\": \"地区管理局\"}]','{\"correctAnswer\": \"B\"}','A中国民用航空局（CAAC）是无人机驾驶员资质管理的法定主管部门，负责制定相关政策及标准。‌‌执照的制定、审核及最终颁发权限归属民航局下属的飞行标准司。‌‌\nB中国AOPA是中国民用航空局（CAAC）授权的无人机资质管理机构，负责视距外运行或空机重量大于7公斤的无人机驾驶员资质认证。其颁发的合格证为“训练合格证”，但实际效力等同于官方执照，且与民航局同步发放的电子执照形成“双证”体系。民用无人机驾驶航空器系统驾驶员合格证由中国航空器拥有者及驾驶员协会（中国AOPA）颁发‌。\nC‌地区管理局仅‌负责辖区内的监管工作，不直接颁发全国性的驾驶员执照。‌‌',1,9,'raw-bank/无人机飞行手册、法律法规及其他.docx#第9题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(130,NULL,4,'Q-FMR-0011','single_choice','无人机的注册所有者或者运营人应将永久邮寄地址的变更，无人机的销售和______等事项通知局方注册处','B','[{\"optionCode\": \"A\", \"optionContent\": \"试验试飞\"}, {\"optionCode\": \"B\", \"optionContent\": \"无人机注册证书丢失\"}, {\"optionCode\": \"C\", \"optionContent\": \"无人机维修\"}]','{\"correctAnswer\": \"B\"}','根据《民用无人驾驶航空器实名制登记管理规定》，注册所有者或运营人需及时向局方报告永久地址变更、所有权转移（如销售）、无人机灭失/报废或注册证书丢失等情况。\nA选项的“试验试飞”属于飞行活动管理，与注册信息变更无关。\nB选项“证书丢失”会直接影响注册有效性，需上报补办。‌‌‌‌‌‌‌‌\nC选项“维修”通常不涉及注册信息更新。',1,11,'raw-bank/无人机飞行手册、法律法规及其他.docx#第11题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(131,NULL,4,'Q-FMR-0013','single_choice','在中华人民共和国境内飞行的航空器必须遵守统一的飞行规则，该飞行规则应当由 ________制定','C','[{\"optionCode\": \"A\", \"optionContent\": \"民用航空局和中央军委\"}, {\"optionCode\": \"B\", \"optionContent\": \"中央军委\"}, {\"optionCode\": \"C\", \"optionContent\": \"国务院和中央军委\"}]','{\"correctAnswer\": \"C\"}','《中华人民共和国飞行基本规则》第三条规定：“国务院、中央军事委员会统一领导全国飞行管制工作。国务院民用航空主管部门负责全国的飞行管制工作；国家空中交通管制委员会领导全国的飞行管制工作。”因此，该规则的制定需由国务院和中央军委联合进行。',1,13,'raw-bank/无人机飞行手册、法律法规及其他.docx#第13题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(132,NULL,4,'Q-FMR-0015','single_choice','任何单位或者个人设计民用航空器，应当向民航局申请','C','[{\"optionCode\": \"A\", \"optionContent\": \"适航证\"}, {\"optionCode\": \"B\", \"optionContent\": \"生产许可证\"}, {\"optionCode\": \"C\", \"optionContent\": \"型号合格证\"}]','{\"correctAnswer\": \"C\"}','A‌生产许可证‌：生产阶段需申请的证件，需基于型号合格证并经航空工业部同意后向民航局申请，企业需获得此证方可合法生产民用航空器，是生产活动的直接准入前提。。‌‌\nB‌适航证‌：颁发给单架航空器，证明其符合安全飞行标准，是民用航空器飞行必备证件，由民航局在通过生产许可审定后颁发，或对特殊情况下生产的航空器逐一审查后颁发。‌‌‌‌‌‌\nC型号合格证‌设计阶段需申请的法定证件，证明航空器设计符合适航标准。根据《中华人民共和国民用航空器适航管理条例》及相关法规，设计单位或个人需持航空工业部审核批准文件向民航局申请，民航局通过型号合格审定后颁发。',1,15,'raw-bank/无人机飞行手册、法律法规及其他.docx#第15题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(133,NULL,4,'Q-FMR-0017','single_choice','民用航空适航管理是对哪几个方面进行管理','A','[{\"optionCode\": \"A\", \"optionContent\": \"发动机．螺旋桨和航空器上的设备\"}, {\"optionCode\": \"B\", \"optionContent\": \"航空器．发动机．螺旋桨\"}, {\"optionCode\": \"C\", \"optionContent\": \"航空器．发动机\"}]','{\"correctAnswer\": \"A\"}','民用航空适航管理是对航空器及其相关部件进行管理，以确保其安全性和适航性。适航管理的主要内容包括对航空器、发动机、螺旋桨和航空器上的设备进行严格的检查和认证，以确保这些部件符合安全标准和适航要求。\n发动机：航空器的动力系统，必须经过严格的测试和认证，以确保其性能和安全性。\n螺旋桨：对于使用螺旋桨的航空器，螺旋桨的性能和安全性也需要进行管理。\n航空器上的设备：包括各种机载设备和系统，如导航设备、通信设备等，这些设备的性能和可靠性直接影响航空器的安全性。',1,17,'raw-bank/无人机飞行手册、法律法规及其他.docx#第17题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(134,NULL,4,'Q-FMR-0019','single_choice','民用航空器必须具有民航局颁发的________方可飞行','A','[{\"optionCode\": \"A\", \"optionContent\": \"适航证\"}, {\"optionCode\": \"B\", \"optionContent\": \"经营许可证\"}, {\"optionCode\": \"C\", \"optionContent\": \"机场使用许可证\"}]','{\"correctAnswer\": \"A\"}','A‌生产许可证‌：生产阶段需申请的证件，需基于型号合格证并经航空工业部同意后向民航局申请，企业需获得此证方可合法生产民用航空器，是生产活动的直接准入前提。。‌‌\nB‌适航证‌：颁发给单架航空器，证明其符合安全飞行标准，是民用航空器飞行必备证件，由民航局在通过生产许可审定后颁发，或对特殊情况下生产的航空器逐一审查后颁发。‌‌‌‌‌‌\nC型号合格证‌设计阶段需申请的法定证件，证明航空器设计符合适航标准。根据《中华人民共和国民用航空器适航管理条例》及相关法规，设计单位或个人需持航空工业部审核批准文件向民航局申请，民航局通过型号合格审定后颁发。',1,19,'raw-bank/无人机飞行手册、法律法规及其他.docx#第19题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(135,NULL,4,'Q-FMR-0021','single_choice','《中华人民共和国民用航空法》自________起施行','B','[{\"optionCode\": \"A\", \"optionContent\": \"1996 年 1 月 1 日\"}, {\"optionCode\": \"B\", \"optionContent\": \"1996 年 3 月 1 日\"}, {\"optionCode\": \"C\", \"optionContent\": \"1997 年 1 月 1 日\"}]','{\"correctAnswer\": \"B\"}','《中华人民共和国民用航空法》是1995年10月30日经第八届全国人大常委会第16次会议审议通过，并于1996年3月1日起正式施行。这是新中国成立以来第一部规范民用航空活动的法律，标志着我国民用航空事业进入了一个新的发展阶段，具有重要的历史意义。该法律的实施为我国民用航空事业的健康发展提供了法律保障和规范。',1,21,'raw-bank/无人机飞行手册、法律法规及其他.docx#第21题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(136,NULL,4,'Q-FMR-0023','single_choice','下列航空法律法规中级别最高的是','B','[{\"optionCode\": \"A\", \"optionContent\": \"《中华人民共和国飞行基本规则》\"}, {\"optionCode\": \"B\", \"optionContent\": \"《中华人民共和国民用航空法》\"}, {\"optionCode\": \"C\", \"optionContent\": \"《中华人民共和国搜寻援救民用航空器的规定》\"}]','{\"correctAnswer\": \"B\"}','我国法律体系效力层级为：宪法>法律>行政法规>部门规章。‌‌法律由全国人大及其常委会制定；行政法规由国务院制定；部门规章由相关部委制定。\nA《中华人民共和国民用航空法》‌：由全国人民代表大会常务委员会制定，属于“法律”层级，在中国法律体系中效力仅次于宪法。该法律旨在维护国家的领空主权和民用航空权利，保障民用航空活动安全和有秩序地进行，保护民用航空活动当事人各方的合法权益，促进民用航空事业的发展。\nB‌《中华人民共和国飞行基本规则》‌：由国务院和中央军委联合颁布，属于行政法规层级，其效力低于法律。该规则主要为了维护国家领空主权，规范中华人民共和国境内的飞行活动，保障飞行活动安全有秩序地进行。\nC《中华人民共和国搜寻援救民用航空器的规定》：属于民航局发布的部门规章，效力层级最低。\n综上所述，级别最高的是《中华人民共和国民用航空法》。',1,23,'raw-bank/无人机飞行手册、法律法规及其他.docx#第23题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(137,NULL,4,'Q-FMR-0025','single_choice','《中国民用航空法》中“航空人员 ”是指从事民用航空活动的','B','[{\"optionCode\": \"A\", \"optionContent\": \"空勤人员\"}, {\"optionCode\": \"B\", \"optionContent\": \"空勤人员和地面人员\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行人员和地面人员\"}]','{\"correctAnswer\": \"B\"}','航空人员‌包含两类：\n‌空勤人员‌：直接参与飞行任务的人员，包括驾驶员、领航员、飞行机械人员、飞行通信员和乘务员。‌‌‌‌\n‌地面人员‌：负责飞行保障的地面工作人员，涵盖民用航空器维修人员、空中交通管制员、飞行签派员及航空电台通信员。‌‌\n‌空勤人员‌与“飞行人员”的区别：后者通常仅指驾驶员等直接操作航空器的人员，包括驾驶员、领航员、飞行通信员、飞行机械员等，负责飞行过程中的核心操作和设备控制。‌‌而前者范围更广（如乘务员虽不参与飞行操作，但属于空勤人员）。\n机组‌概念更广泛，包含乘务人员等非直接操作角色，而“飞行人员”特指核心操纵岗位。‌‌‌‌\n“机长和副驾驶”仅涵盖驾驶舱成员，未包含领航、通信等其他关键角色，因此不属于完整定义范畴。‌‌',1,25,'raw-bank/无人机飞行手册、法律法规及其他.docx#第25题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(138,NULL,4,'Q-FMR-0027','single_choice','关于“ 民用航空器国籍 ”正确的是','B','[{\"optionCode\": \"A\", \"optionContent\": \"民用航空器可以不进行国籍登记而投入运行\"}, {\"optionCode\": \"B\", \"optionContent\": \"民用航空器只能具有一国国籍\"}, {\"optionCode\": \"C\", \"optionContent\": \"自外国租赁的民用航空器不能申请我国国籍\"}]','{\"correctAnswer\": \"B\"}','A民用航空器必须进行国籍登记才能投入运行。每架民用航空器在投入运行前，必须在某个国家进行国籍登记，否则无法合法飞行。\nB民用航空器只能具有一国国籍。根据国际航空法，一架民用航空器不能同时拥有两个国家的国籍，只能在一个国家进行国籍登记。这是为了明确航空器的法律归属和管理责任，避免法律上的冲突和管辖问题。\nC自外国租赁的民用航空器可以申请我国国籍。如果符合相关法律法规，从外国租赁的民用航空器也可以申请在我国进行国籍登记。',1,27,'raw-bank/无人机飞行手册、法律法规及其他.docx#第27题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(139,NULL,4,'Q-FMR-0029','single_choice','民用无人驾驶航空器系统驾驶员合格证由哪个部门颁发','B','[{\"optionCode\": \"A\", \"optionContent\": \"民航局下属司（局）\"}, {\"optionCode\": \"B\", \"optionContent\": \"中国航空器拥有者及驾驶员协会（中国 AOPA．）\"}, {\"optionCode\": \"C\", \"optionContent\": \"地区管理局\"}]','{\"correctAnswer\": \"B\"}','A中国民用航空局（CAAC）是无人机驾驶员资质管理的法定主管部门，负责制定相关政策及标准。‌‌执照的制定、审核及最终颁发权限归属民航局下属的飞行标准司。‌‌\nB中国AOPA是中国民用航空局（CAAC）授权的无人机资质管理机构，负责视距外运行或空机重量大于7公斤的无人机驾驶员资质认证。其颁发的合格证为“训练合格证”，但实际效力等同于官方执照，且与民航局同步发放的电子执照形成“双证”体系。民用无人机驾驶航空器系统驾驶员合格证由中国航空器拥有者及驾驶员协会（中国AOPA）颁发‌。\nC‌地区管理局仅‌负责辖区内的监管工作，不直接颁发全国性的驾驶员执照。',1,29,'raw-bank/无人机飞行手册、法律法规及其他.docx#第29题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(140,NULL,4,'Q-FMR-0031','single_choice','从事飞行的民用航空器不需要携带的文件是','B','[{\"optionCode\": \"A\", \"optionContent\": \"飞行人员相应的执照或合格证\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞行记录薄\"}, {\"optionCode\": \"C\", \"optionContent\": \"民用航空器适航证书\"}]','{\"correctAnswer\": \"B\"}','民用航空器需携带的核心文件包括：\nA‌飞行人员相应的执照或合格证‌（如飞行员执照或无人机驾驶员合格证）；‌‌‌‌\nC‌民用航空器适航证书‌（证明航空器符合安全标准）。\n民用航空器非必需性文件：‌‌‌‌\nB‌飞行记录薄‌通常指航空器的维护和飞行数据记录，这类文件一般保存在地面或定期检查中，无需每次飞行时随身携带。',1,31,'raw-bank/无人机飞行手册、法律法规及其他.docx#第31题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(141,NULL,4,'Q-FMR-0033','single_choice','民用无人驾驶航空器系统驾驶员合格证申请人必须在民用无人驾驶航空器系统上训练不少于多少小时的飞行训练时 间','B','[{\"optionCode\": \"A\", \"optionContent\": \"56\"}, {\"optionCode\": \"B\", \"optionContent\": \"44 C.100\"}]','{\"correctAnswer\": \"B\"}','根据民航局的规定，民用无人驾驶航空器系统驾驶员合格证申请人需要完成一定的飞行训练时间，以确保其具备足够的飞行经验和技能。\n具体要求是，申请人必须在民用无人驾驶航空器系统上训练不少于44小时的飞行训练时间，以通过相关考核并获得合格证。民用无人驾驶航空器系统驾驶员机长合格证申请人需要完成不少于56小时的飞行训练时间。',1,33,'raw-bank/无人机飞行手册、法律法规及其他.docx#第33题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(142,NULL,4,'Q-FMR-0035','single_choice','民用无人驾驶航空器系统视距内运行是指航空器处于驾驶员或观测员目视视距内半径 ______米，相对高度低于 ______米的区域内','B','[{\"optionCode\": \"A\", \"optionContent\": \"120，500\"}, {\"optionCode\": \"B\", \"optionContent\": \"500，120\"}, {\"optionCode\": \"C\", \"optionContent\": \"100，50\"}]','{\"correctAnswer\": \"B\"}','视距内运行的范围是航空器处于驾驶员或观测员目视视距内半径500米，相对高度低于120米的区域内。这是为了保证驾驶员或观测员能够通过目视直接看到航空器，及时发现和处理可能出现的问题。',1,35,'raw-bank/无人机飞行手册、法律法规及其他.docx#第35题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(143,NULL,4,'Q-FMR-0037','single_choice','下列说法中，哪一种对无人机教员合格证申请人的要求是必要的','B','[{\"optionCode\": \"A\", \"optionContent\": \"具备无人机应急处理程序方面的技术\"}, {\"optionCode\": \"B\", \"optionContent\": \"在所申请的无人机上担任机长经历时间多于 100 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在所申请的无人机上飞行经历不少于 100 小时\"}]','{\"correctAnswer\": \"B\"}','A具备无人机应急处理程序方面的技术是重要的，但这并不是唯一的必要条件。\nB在所申请的无人机上担任机长经历时间多于100小时是必要的，因为这表明申请人有足够的实际操作经验，能够处理各种飞行情况，确保教学过程中的安全和有效性。\nC在所申请的无人机上飞行经历不少于100小时也是重要的，但这通常是作为机长经历的一部分。',1,37,'raw-bank/无人机飞行手册、法律法规及其他.docx#第37题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(144,NULL,4,'Q-FMR-0039','single_choice','下列情况下，无人机系统驾驶员由局方实施管理','B','[{\"optionCode\": \"A\", \"optionContent\": \"在融合空域运行的轻型无人机\"}, {\"optionCode\": \"B\", \"optionContent\": \"在融合空域运行的小型无人机\"}, {\"optionCode\": \"C\", \"optionContent\": \"在隔离空域内超视距运行的无人机\"}]','{\"correctAnswer\": \"B\"}','‌融合空域‌：涉及有人驾驶航空器与无人机的混合运行区域，安全标准更高，需由中国民用航空局（CAAC）直接管理。‌‌\n‌隔离空域‌：专门划定的无人机运行区域，若无人机在此区域内超视距（超出直接视线范围）飞行，驾驶员资质可由行业协会负责管理。',1,39,'raw-bank/无人机飞行手册、法律法规及其他.docx#第39题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(145,NULL,4,'Q-FMR-0042','single_choice','在融合空域运行的大型无人机驾驶员，应至少持有带有飞机或直升机等级的','A','[{\"optionCode\": \"A\", \"optionContent\": \"商照和仪表等级\"}, {\"optionCode\": \"B\", \"optionContent\": \"私照\"}, {\"optionCode\": \"C\", \"optionContent\": \"商照\"}]','{\"correctAnswer\": \"A\"}','私照：适用于一般私人飞行活动，对于小型无人机驾驶员来说，持有私照即可满足在融合空域3,000米以下运行的要求。\n商照：融合空域3000米以上高度运行的小型无人机属于高风险操作范畴‌，驾驶员必须持有商用驾驶员执照（商照），并具备飞机或直升机等级的资质认证。虽然商业驾驶员执照允许商业飞行，但没有仪表等级的商照在融合空域中可能不足以应对所有飞行条件。\n商照和仪表等级：在融合空域运行的大型无人机驾驶员应至少持有带有飞机或直升机等级的商用驾驶员执照和仪表等级。这是因为大型无人机在融合空域中需要具备与有人驾驶航空器相当的飞行能力和操作技能，以确保飞行安全。\n航线运输执照：对于机长而言，要求更高，必须持有航线运输驾驶员执照。航线运输驾驶员执照是最高级别的飞行执照，表明持有者具备在复杂飞行环境和长距离飞行中的操作能力，能够胜任复杂的飞行任务和应对各种突发情况。',1,42,'raw-bank/无人机飞行手册、法律法规及其他.docx#第42题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(146,NULL,4,'Q-FMR-0044','single_choice','谁对机组成员遵守飞行基本规则负责','B','[{\"optionCode\": \"A\", \"optionContent\": \"航空单位负责人\"}, {\"optionCode\": \"B\", \"optionContent\": \"机长\"}, {\"optionCode\": \"C\", \"optionContent\": \"民航局及其地区管理局\"}]','{\"correctAnswer\": \"B\"}','A航空单位负责人承担机构层面的合规管理职责，包括制定内部规章制度、组织培训考核等系统性保障措施，但不直接干预具体飞行任务中的规则执行。\nB机长作为飞行任务的核心指挥者，需确保机组人员在执行任务过程中严格遵守飞行基本规则，包括操作规范、应急处置和纪律要求。这一规定体现了飞行安全责任与指挥权相统一的原则。‌‌‌‌\nC民航局及其地区管理机构作为行业主管部门，主要负责制定规章标准、实施安全监管和开展行政执法等工作，属于外部监督主体而非直接责任主体。',1,44,'raw-bank/无人机飞行手册、法律法规及其他.docx#第44题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(147,NULL,4,'Q-FMR-0046','single_choice','飞行高度层应当根据______计算','B','[{\"optionCode\": \"A\", \"optionContent\": \"标准大气压条件下平均平面\"}, {\"optionCode\": \"B\", \"optionContent\": \"标准大气压条件下假定海平面\"}, {\"optionCode\": \"C\", \"optionContent\": \"实际大气压条件下假定海平面\"}]','{\"correctAnswer\": \"B\"}','标准大气压条件下假定海平面：这是国际航空标准，用于统一高度测量。标准大气压条件下假定海平面是指在标准大气压（1013.25 hPa）下，假定海平面的高度作为基准面，这样可以确保所有飞行器在不同地点和不同天气条件下都能使用相同的基准面进行高度测量，避免因实际大气压变化而引起的高度误差。',1,46,'raw-bank/无人机飞行手册、法律法规及其他.docx#第46题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:29:40'),(148,NULL,4,'Q-FMR-0048','single_choice','飞行高度层应当根据______配备','C','[{\"optionCode\": \"A\", \"optionContent\": \"航线或航路走向．航空器性能．飞行区域以及航线的地形．天气和飞行情况等\"}, {\"optionCode\": \"B\", \"optionContent\": \"飞行任务的性质．航空器等级．飞行区域以及航线的地形．天气和飞行情况等\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行任务的性质．航空器性能．飞行区域以及航线的地形．天气和飞行情况等\"}]','{\"correctAnswer\": \"C\"}','飞行高度层的配备需综合考虑以下关键因素：‌‌\n‌飞行任务的性质‌：包括任务类型（如民用运输、军事训练、科研试飞等）的优先级和特殊需求。\n‌航空器性能‌：涉及飞行器的爬升能力、巡航速度、最大飞行高度等技术参数。\n‌飞行区域特性‌：涵盖空域分类（如航路、机场空域）、地理环境（如高原、山区）及障碍物分布。\n‌航线条件‌：包含地形起伏、气象条件（如气压、风速）和实时飞行状况。‌‌‌‌',1,48,'raw-bank/无人机飞行手册、法律法规及其他.docx#第48题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(149,NULL,4,'Q-FMR-0054','single_choice','旋翼机飞行时间的含义是指','C','[{\"optionCode\": \"A\", \"optionContent\": \"自旋翼机起飞离地到着陆接地的瞬间\"}, {\"optionCode\": \"B\", \"optionContent\": \"自旋翼机起飞滑跑至着陆滑跑终止的瞬间\"}, {\"optionCode\": \"C\", \"optionContent\": \"自旋翼机旋翼开始转动至旋翼停止转动的瞬间\"}]','{\"correctAnswer\": \"C\"}','旋翼机飞行时间是指从旋翼开始转动到旋翼停止转动的整个时间段，而不是从起飞离地到着陆接地或从起飞滑跑到着陆滑跑终止的时间。旋翼机的飞行时间通常是从旋翼开始转动的那一刻开始计算，直到旋翼完全停止转动为止，这段时间包括了起飞、飞行和着陆的全过程。',1,54,'raw-bank/无人机飞行手册、法律法规及其他.docx#第54题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:29:40'),(150,NULL,4,'Q-FMR-0056','single_choice','执行昼间专业任务的航空器,在平原．丘陵地区进行作业飞行时, 起飞时间最早不得早于日出前','C','[{\"optionCode\": \"A\", \"optionContent\": \"10 分钟\"}, {\"optionCode\": \"B\", \"optionContent\": \"20 分钟\"}, {\"optionCode\": \"C\", \"optionContent\": \"30 分钟\"}]','{\"correctAnswer\": \"C\"}','执行昼间作业任务的航空器,在山区进行作业飞行时，起飞时间最早不得早于日出前20分钟，平原、丘陵地区进行作业飞行时，起飞时间最早不得早于日出前30分钟。在山区进行作业飞行时,着陆时间最晚不得晚于日落前15分钟。\n飞行最低天气标准。\n在平原地区农业作业飞行的最低天气标准是，云高不低于200米，水平能见度不小于5公里。\n在广阔水域上空进行各种渔业飞行的最低天气标准是，云高不得低于200米，水平能见度不得小于3公里。\n在丘陵、山区、高原进行农业作业飞行的最低天气标准是，云高距作业区的最高点不低于300米，水平能见度不小于5公里。',1,56,'raw-bank/无人机飞行手册、法律法规及其他.docx#第56题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(151,NULL,4,'Q-FMR-0059','single_choice','在丘陵、山区、高原进行农业作业飞行的最低天气标准是','C','[{\"optionCode\": \"A\", \"optionContent\": \"云高距作业区的最高点不低于 150 米,能见度不小于 3 公里\"}, {\"optionCode\": \"B\", \"optionContent\": \"云高距作业区的最高点不低于 200 米,能见度不小于 5 公里\"}, {\"optionCode\": \"C\", \"optionContent\": \"云高距作业区的最高点不低于 300 米,能见度不小于 5 公里\"}]','{\"correctAnswer\": \"C\"}','执行昼间作业任务的航空器,在山区进行作业飞行时，起飞时间最早不得早于日出前20分钟，平原、丘陵地区进行作业飞行时，起飞时间最早不得早于日出前30分钟。在山区进行作业飞行时,着陆时间最晚不得晚于日落前15分钟。\n飞行最低天气标准。\n在平原地区农业作业飞行的最低天气标准是，云高不低于200米，水平能见度不小于5公里。\n在广阔水域上空进行各种渔业飞行的最低天气标准是，云高不得低于200米，水平能见度不得小于3公里。\n在丘陵、山区、高原进行农业作业飞行的最低天气标准是，云高距作业区的最高点不低于300米，水平能见度不小于5公里。',1,59,'raw-bank/无人机飞行手册、法律法规及其他.docx#第59题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(152,NULL,4,'Q-FMR-0061','single_choice','训练时间，是指受训人在下列方面从授权教员处接受训练的时间','C','[{\"optionCode\": \"A\", \"optionContent\": \"飞行中\"}, {\"optionCode\": \"B\", \"optionContent\": \"地面上．飞行模拟机或飞行训练器上\"}, {\"optionCode\": \"C\", \"optionContent\": \"飞行中．地面上，飞行模拟机或飞行练习器上\"}]','{\"correctAnswer\": \"C\"}','训练时间是指受训人在不同环境下接受训练的时间，包括飞行中、地面上以及使用飞行模拟机或飞行训练器的时间。\n飞行中：指受训人在实际飞行过程中接受训练的时间。\n地面上：指受训人在地面上进行理论学习和实际操作训练的时间。\n飞行模拟机或飞行训练器上：指受训人在模拟飞行设备上进行训练的时间。',1,61,'raw-bank/无人机飞行手册、法律法规及其他.docx#第61题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(153,NULL,4,'Q-FMR-0063','single_choice','学生驾驶员在单飞之前必须在其飞行经历记录本上，有授权教员的签字，证明其在单飞日期之前______天内接受了 所飞型号航空器的训练。','A','[{\"optionCode\": \"A\", \"optionContent\": \"90\"}, {\"optionCode\": \"B\", \"optionContent\": \"60\"}, {\"optionCode\": \"C\", \"optionContent\": \"30\"}]','{\"correctAnswer\": \"A\"}','授权教员签字‌：签字需由具备资质的飞行教员完成，且需在学员的飞行经历记录本中明确标注教学的内容、课时、日期以及所飞机型。‌‌‌‌\n‌训练时长限制‌：学员必须在单飞前90天内完成相关型号的训练，否则无法通过教员的签字认证。‌‌\n‌记录本要求‌：飞行经历记录本需详细记录每次训练的时间、机型、教学内容等关键信息，以备后续审核。',1,63,'raw-bank/无人机飞行手册、法律法规及其他.docx#第63题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(154,NULL,4,'Q-FMR-0065','single_choice','参加理论考试或实践考试的申请人在参加考试前','C','[{\"optionCode\": \"A\", \"optionContent\": \"应当具有地面教员或飞行教员签注的已完成有关地面理论或飞行训练的证明\"}, {\"optionCode\": \"B\", \"optionContent\": \"应当具有地面教员和飞行教员推荐其参加考试的证明。\"}, {\"optionCode\": \"C\", \"optionContent\": \"以上二者缺一不可\"}]','{\"correctAnswer\": \"C\"}','申请人应当具有地面教员或飞行教员签注的已完成有关地面理论或飞行训练的证明。这是为了确保申请人已经接受了必要的培训和指导，具备了参加考试的基本条件。同时，申请人还应当具有地面教员和飞行教员推荐其参加考试的证明。这是为了确保申请人不仅完成了训练，还得到了教员的认可，认为其已经达到了参加考试的水平。',1,65,'raw-bank/无人机飞行手册、法律法规及其他.docx#第65题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(155,NULL,4,'Q-FMR-0067','single_choice','下列说法中，哪一种对无人机教员合格证申请人的要','B','[{\"optionCode\": \"A\", \"optionContent\": \"具备无人机应急处理程序方面的技术\"}, {\"optionCode\": \"B\", \"optionContent\": \"在所申请的无人机上担任机长经历时间多于 100 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在所申请的无人机上飞行经历不少于 100 小时\"}]','{\"correctAnswer\": \"B\"}','A具备无人机应急处理程序方面的技术是重要的，但这并不是唯一的必要条件。\nB在所申请的无人机上担任机长经历时间多于100小时是必要的，因为这表明申请人有足够的实际操作经验，能够处理各种飞行情况，确保教学过程中的安全和有效性。\nC在所申请的无人机上飞行经历不少于100小时也是重要的，但这通常是作为机长经历的一部分。',1,67,'raw-bank/无人机飞行手册、法律法规及其他.docx#第67题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(156,NULL,4,'Q-FMR-0069','single_choice','每个飞行教员必须将 CCA61 部要求的记录保存','B','[{\"optionCode\": \"A\", \"optionContent\": \"一年\"}, {\"optionCode\": \"B\", \"optionContent\": \"三年\"}, {\"optionCode\": \"C\", \"optionContent\": \"五年\"}]','{\"correctAnswer\": \"B\"}','根据中国民用航空规章CCAR-61部第61.51条的规定，每个飞行教员必须将相关记录保存至少‌三年‌。具体要求如下：\n‌记录内容‌：包括学员训练记录、考试结果、飞行经历时间证明等与教学和考试相关的文件。‌‌\n‌保存期限‌：需完整保存至少3年，以便民航管理部门检查。‌‌\n‌例外情况‌：若涉及刑事案件调查或法律程序，记录保存时间可能延长至案件结束。',1,69,'raw-bank/无人机飞行手册、法律法规及其他.docx#第69题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(157,NULL,4,'Q-FMR-0071','single_choice','对飞行教员合格证申请人的知识要求为','A','[{\"optionCode\": \"A\", \"optionContent\": \"教学原理，所申请飞行教员合格证航空器类别的驾驶员．驾驶员机长合格证要求的航空知识，及所申请飞行教员合 格证等级要求的航空知识\"}, {\"optionCode\": \"B\", \"optionContent\": \"教学原理，所申请飞行教员合格证航空器类别的驾驶员．商用和航线驾驶员执照要求的航空知识，及所申请飞行教 员执照航空器类别的仪表等级要求的航空知识\"}, {\"optionCode\": \"C\", \"optionContent\": \"教学原理，所申请飞行教员执照航空器类别的私用．商用和航线驾驶员执照要求的航空知识\"}]','{\"correctAnswer\": \"A\"}','飞行教员合格证申请人的知识要求包括以下三方面：\n‌教学原理‌：需掌握航空教学的理论与方法，包括课程设计、学员评估等。‌‌‌‌\n‌航空器类别知识‌：需具备所申请航空器类别（如固定翼、直升机等）的驾驶员机长合格证要求的航空知识，涵盖飞行操作、系统原理等。‌‌‌‌\n‌等级要求知识‌：需满足所申请教员合格证等级（如初级、高级）对应的专项知识，例如仪表飞行规则或特定机型操作。',1,71,'raw-bank/无人机飞行手册、法律法规及其他.docx#第71题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(158,NULL,4,'Q-FMR-0073','single_choice','下列说法正确的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"飞行教员不得为获得 CCA61 部要求的执照．合格证．等级．运行许可．实践考试或者理论考试权利而为自己进行任 何签字\"}, {\"optionCode\": \"B\", \"optionContent\": \"除非具有局方委任的监察员或考试员资格，否则飞行教员不得为获得 CCA61 部要求的执照．合格证．等级．运行许 可．实践考试或者理论考试权利而为自己进行任何签字\"}, {\"optionCode\": \"C\", \"optionContent\": \"当存在特殊的情况或条件限制时，在获得特别授权和批准后，飞行教员可以为获得 CCA61 部要求的执照．合格 证．等级．运行许可．实践考试或者理论考试权利而为自己进行签字\"}]','{\"correctAnswer\": \"A\"}','根据CCA61部规定，飞行教员禁止为获得相关执照、合格证等权利自行签字，无论是否具备监察员/考试员资格或获得特殊批准。因此：\n选项A正确，因其明确禁止飞行教员为自己签字，且不依赖资格或批准条件。\n选项B错误，因“监察员或考试员资格”并非豁免条件。\n选项C错误，因“特殊批准”无法改变禁令的普遍适用性。',1,73,'raw-bank/无人机飞行手册、法律法规及其他.docx#第73题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(159,NULL,4,'Q-FMR-0075','single_choice','关于通用航空的说法正确的是 ①通用航空企业从事经营性通用航空活动，应当与用户订立书面合同，但是紧急情况下的救灾飞行除外。 ②组织实施作业飞行时，应当采取有效措施，保证飞行安全。 ③组织实施作业飞行时，保护环境和生态平衡，防止对环境．居民．作物或者牲畜等造成损害。 ④从事通用航空活动的，应当投保地面第三人责任险。','B','[{\"optionCode\": \"A\", \"optionContent\": \"①②③\"}, {\"optionCode\": \"B\", \"optionContent\": \"①②③④\"}, {\"optionCode\": \"C\", \"optionContent\": \"①②④\"}]','{\"correctAnswer\": \"B\"}','经营性通用航空活动的核心规定\n‌合同签订义务‌：通用航空企业从事经营性活动时，必须与用户订立书面合同，但紧急救灾飞行可豁免此要求。‌‌‌‌\n‌飞行安全措施‌：作业飞行需采取有效措施保障安全，包括使用适航航空器、持照驾驶员及合规的飞行计划。‌‌‌‌\n‌环境保护责任‌：作业中需防止对生态环境、居民或农作物造成损害，噪声和排放需符合国家标准。‌‌\n‌强制保险要求‌：从事通用航空活动的企业必须投保地面第三人责任险。',1,75,'raw-bank/无人机飞行手册、法律法规及其他.docx#第75题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(160,NULL,4,'Q-FMR-0077','single_choice','直升机按起飞重量大致可分为轻型、中型、重型、巨型直升机四种类型，以下哪一项为中型直升机。______','B','[{\"optionCode\": \"A\", \"optionContent\": \"米-6\"}, {\"optionCode\": \"B\", \"optionContent\": \"米-8\"}, {\"optionCode\": \"C\", \"optionContent\": \"米-26\"}]','{\"correctAnswer\": \"B\"}','轻型直升机‌：起飞重量2-8吨，典型机型包括贝尔206、直-9、云雀Ⅲ等。\n‌中型直升机‌：起飞重量8-15吨，代表机型有米-8、UH-60A（黑鹰）、直-8等。\n‌重型直升机‌：起飞重量15-20吨，如CH-53（种马）系列。\n‌巨型直升机‌：起飞重量超过20吨，例如米-6、CH-47（支奴干）等。',1,77,'raw-bank/无人机飞行手册、法律法规及其他.docx#第77题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(161,NULL,4,'Q-FMR-0079','single_choice','民用无人机系统要求至少______检查一次。','B','[{\"optionCode\": \"A\", \"optionContent\": \"半年\"}, {\"optionCode\": \"B\", \"optionContent\": \"一年\"}, {\"optionCode\": \"C\", \"optionContent\": \"两年\"}]','{\"correctAnswer\": \"B\"}','在民用无人机相关规定中，明确要求民用无人机系统至少一年检查一次。这是行业内基于保障无人机安全运行等多方面因素制定的标准规范。',1,79,'raw-bank/无人机飞行手册、法律法规及其他.docx#第79题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(162,NULL,4,'Q-FMR-0081','single_choice','无人机年度检查，要求。','A','[{\"optionCode\": \"A\", \"optionContent\": \"至少一年一次\"}, {\"optionCode\": \"B\", \"optionContent\": \"两年一次\"}, {\"optionCode\": \"C\", \"optionContent\": \"视无人机状态确定\"}]','{\"correctAnswer\": \"A\"}','解析：在民用无人机相关规定中，明确要求民用无人机系统至少一年检查一次。这是行业内基于保障无人机安全运行等多方面因素制定的标准规范。',1,81,'raw-bank/无人机飞行手册、法律法规及其他.docx#第81题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(163,NULL,4,'Q-FMR-0083','single_choice','无人机的检查应当遵循。','A','[{\"optionCode\": \"A\", \"optionContent\": \"制造商的最新维护手册\"}, {\"optionCode\": \"B\", \"optionContent\": \"随机附带维护手册\"}, {\"optionCode\": \"C\", \"optionContent\": \"无人机飞行员经验\"}]','{\"correctAnswer\": \"A\"}','A制造商的最新维护手册是经过厂家不断更新完善的，涵盖了该型号无人机最新的技术信息、检查标准和维护方法等。随着技术发展和对无人机认识的深入，制造商可能会对原有的检查和维护要点进行修正和补充，所以遵循最新维护手册能确保按照最科学、最准确的方式对无人机进行检查，保证无人机处于良好运行状态。\nB随机附带维护手册在无人机生产出厂时配备，相对固定。随着时间推移，制造商可能发现新的问题或有更好的检查维护方式，但随机附带手册可能无法及时体现这些更新内容，相比之下，它不如最新维护手册全面和与时俱进。\nC无人机飞行员经验虽然有一定参考价值，但每个飞行员的操作习惯、飞行环境等不同，经验具有主观性和局限性。而且飞行员经验不一定涵盖了无人机全面、系统的检查要点，不能作为普遍遵循的标准。',1,83,'raw-bank/无人机飞行手册、法律法规及其他.docx#第83题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(164,NULL,4,'Q-FMR-0085','single_choice','中华人民共和国境外的维修单位或者个人，从事在中华人民共和国注册登记的民用航空器的维修','C','[{\"optionCode\": \"A\", \"optionContent\": \"必须取得当地政府民航主管部门颁发的维修许可证\"}, {\"optionCode\": \"B\", \"optionContent\": \"不必申请维修许可证\"}, {\"optionCode\": \"C\", \"optionContent\": \"必须取得我国民航总局颁发的维修许可证\"}]','{\"correctAnswer\": \"C\"}','A当地政府民航主管部门，这里的“当地”如果指境外维修单位或个人所在地区的政府民航主管部门，由于维修的是我国注册登记的民用航空器，境外当地政府民航主管部门的许可并不能满足我国对于本国注册民用航空器维修管理的要求。我国对于本国注册民用航空器的维修管理有自己独立的规定体系，所以不能仅取得当地政府民航主管部门颁发的维修许可证。\nB民用航空器的维修涉及飞行安全等重要方面，对于在我国注册登记的民用航空器，不可能不进行许可管理，不申请维修许可证会使维修行为缺乏规范和监管，不利于保障民用航空安全。\nC中华人民共和国注册登记的民用航空器，其相关维修活动需要受到我国民航管理部门的规范和监管。我国民航总局作为我国民用航空领域的主管部门，为确保维修质量和飞行安全，规定中华人民共和国境外的维修单位或者个人，从事这类维修必须取得我国民航总局颁发的维修许可证。',1,85,'raw-bank/无人机飞行手册、法律法规及其他.docx#第85题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(165,NULL,4,'Q-FMR-0087','single_choice','下列哪种感觉是无人机操纵员在操纵无人机时无法感知的：','C','[{\"optionCode\": \"A\", \"optionContent\": \"视觉\"}, {\"optionCode\": \"B\", \"optionContent\": \"听觉\"}, {\"optionCode\": \"C\", \"optionContent\": \"前庭觉\"}]','{\"correctAnswer\": \"C\"}','A无人机操纵员可以通过地面站的显示屏或者第一人称视角（FPV）设备等看到无人机的飞行状态、周围环境等画面信息，这依靠的就是视觉。所以无人机操纵员在操纵过程中能够运用视觉来获取相关信息辅助操作。\nB无人机在飞行时，其电机运转等会产生声音，操纵员可以通过听觉感知无人机是否有异常声响，比如电机运转声音是否平稳等，以此来判断无人机的工作状态。同时，地面站等设备在发出警报等信息时也可能伴随声音提示，操纵员能利用听觉接收这些信息。所以听觉也是操纵员在操纵无人机时可以感知的。\nC前庭觉是人体对自身运动状态和头在空间位置的一种感觉，主要由内耳中的前庭器官感受。无人机操纵员通常在地面进行操作，自身并没有像无人机那样实际在空中飞行、进行各种姿态变化。所以操纵员无法像在自身飞行时那样通过前庭器官感知到类似的运动状态和空间位置变化，即无人机操纵员在操纵无人机时无法感知前庭觉。',1,87,'raw-bank/无人机飞行手册、法律法规及其他.docx#第87题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(166,NULL,4,'Q-FMR-0089','single_choice','当给大型无人机加油时为预防静电带来的危害应注意','C','[{\"optionCode\": \"A\", \"optionContent\": \"检查电瓶和店门是否关掉\"}, {\"optionCode\": \"B\", \"optionContent\": \"油车是否接地\"}, {\"optionCode\": \"C\", \"optionContent\": \"将飞机加油车和加油枪用连线接地\"}]','{\"correctAnswer\": \"C\"}','A检查电瓶和点火电门是否关断，电瓶和点火电门主要与无人机的电气启动及相关电路系统有关，其状态与预防加油时静电危害并无直接关联。静电危害主要是由于加油过程中油品流动等产生静电积累，若不及时导走可能引发危险，而电瓶和点火电门的关断不能有效导走加油过程产生的静电。\nB油车是否接地，仅油车接地虽然能导走油车自身产生的部分静电，但在加油过程中，飞机和加油枪也会因油品流动等产生静电。如果飞机和加油枪的静电不能及时导走，仍可能在飞机、加油枪与油车之间形成电位差，从而引发静电放电等危险情况。所以仅油车接地不够全面。\nC将飞机、加油车和加油枪用连线接地，这样可以使飞机、加油车和加油枪形成一个等电位体，并且都与大地相连。在加油过程中，无论飞机、加油车还是加油枪产生静电，都能通过连线及时导走，消除它们之间的电位差，极大程度降低因静电引发火灾、爆炸等危险的可能性，是预防静电危害较为全面和有效的措施。',1,89,'raw-bank/无人机飞行手册、法律法规及其他.docx#第89题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(167,NULL,4,'Q-FMR-0091','single_choice','昼间飞行的含义指的是','A','[{\"optionCode\": \"A\", \"optionContent\": \"从日出到日落之间的飞行\"}, {\"optionCode\": \"B\", \"optionContent\": \"从天黑到天亮之间的飞行\"}, {\"optionCode\": \"C\", \"optionContent\": \"从最亮到日落之间的飞行\"}]','{\"correctAnswer\": \"A\"}','在航空规范里，日落和日出是明确的时间节点，“从日落到日出之间的飞行”清晰界定了夜间飞行的时间范围，而白天的时间范围一般是以日出到日落来界定的。',1,91,'raw-bank/无人机飞行手册、法律法规及其他.docx#第91题','normal','online',0,'2026-05-13 22:29:40','2026-05-13 22:38:14'),(168,NULL,4,'Q-FMR-0093','single_choice','下列不属于对无人机机长训练要求的是','C','[{\"optionCode\": \"A\", \"optionContent\": \"在模拟器实施系统检查程序，不少于 1 小时\"}, {\"optionCode\": \"B\", \"optionContent\": \"在实物训练系统实施系统检查程序，不少于 3 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"取得仪表资格\"}, {\"optionCode\": \"A\", \"optionContent\": \"有参与研制飞行模拟器经历\"}, {\"optionCode\": \"B\", \"optionContent\": \"在实物训练系统实施正常飞行程序指挥，不少于 10 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在模拟器实施正常飞行程序指挥，不少于 3 小时\"}, {\"optionCode\": \"A\", \"optionContent\": \"在模拟器实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时\"}, {\"optionCode\": \"B\", \"optionContent\": \"在模拟器实施正常飞行程序检查，不少于 3 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在实物训练系统实施正常飞行程序检查，不少于 10 小时\"}, {\"optionCode\": \"A\", \"optionContent\": \"在模拟器实施应急飞行程序操作，包括发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时\"}, {\"optionCode\": \"B\", \"optionContent\": \"在模拟器实施正常飞行程序指挥，不少于 3 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在实物训练系统实施正常飞行程序指挥，不少于 10 小时\"}, {\"optionCode\": \"A\", \"optionContent\": \"在模拟器实施飞行前检查，不少于 1 小时\"}, {\"optionCode\": \"B\", \"optionContent\": \"在实物训练系统实施飞行前检查程序，不少于 3 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在实物训练系统实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 10 小时\"}, {\"optionCode\": \"A\", \"optionContent\": \"在模拟器实施正常飞行程序操作，不少于 3 小时\"}, {\"optionCode\": \"B\", \"optionContent\": \"在实物训练系统实施正常飞行程序操作，不少于 10 小时\"}, {\"optionCode\": \"C\", \"optionContent\": \"在模拟器实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时\"}, {\"optionCode\": \"A\", \"optionContent\": \"①③\"}, {\"optionCode\": \"B\", \"optionContent\": \"①②③\"}, {\"optionCode\": \"C\", \"optionContent\": \"②③\"}, {\"optionCode\": \"A\", \"optionContent\": \"副驾驶时间\"}, {\"optionCode\": \"B\", \"optionContent\": \"带飞时间\"}, {\"optionCode\": \"C\", \"optionContent\": \"机长时间\"}, {\"optionCode\": \"A\", \"optionContent\": \"1 个月\"}, {\"optionCode\": \"B\", \"optionContent\": \"3 个月\"}, {\"optionCode\": \"C\", \"optionContent\": \"半年\"}, {\"optionCode\": \"A\", \"optionContent\": \"5 米 B.10 米 C.15 米\"}, {\"optionCode\": \"A\", \"optionContent\": \"①②④\"}, {\"optionCode\": \"B\", \"optionContent\": \"①②③④ C.②③④\"}, {\"optionCode\": \"A\", \"optionContent\": \"两者都有\"}, {\"optionCode\": \"B\", \"optionContent\": \"被动反馈系统是指航空器被雷达、ADS-B 系统、北斗等手段从地面进行监视的系统，该反馈信息不经过运营人\"}, {\"optionCode\": \"C\", \"optionContent\": \"主动反馈系统，是指运营人主动将航空器的运行信息发送给监视系统\"}, {\"optionCode\": \"A\", \"optionContent\": \"3 到 6 个月\"}, {\"optionCode\": \"B\", \"optionContent\": \"1 到 6 个月\"}, {\"optionCode\": \"C\", \"optionContent\": \"1 到 3 个月\"}, {\"optionCode\": \"A\", \"optionContent\": \"①②\"}, {\"optionCode\": \"B\", \"optionContent\": \"①③\"}, {\"optionCode\": \"C\", \"optionContent\": \"①②③\"}, {\"optionCode\": \"A\", \"optionContent\": \"①②③\"}, {\"optionCode\": \"B\", \"optionContent\": \"①③④\"}, {\"optionCode\": \"C\", \"optionContent\": \"①②③④\"}, {\"optionCode\": \"A\", \"optionContent\": \"①②③